"""Chemistry practicals (classes 10–12 and UG) on the chemistry engine, and
the forensic labs that share its benches (ink chromatography, presumptive
spot tests)."""


def add(lab, W, Q):
    BURETTE = W('Burette (50 mL) with stand', 'स्टैंड सहित ब्यूरेट (50 mL)', 'ಸ್ಟ್ಯಾಂಡ್ ಸಹಿತ ಬ್ಯೂರೆಟ್ (50 mL)')
    PIPETTE = W('Pipette (10 mL) and conical flask', 'पिपेट (10 mL) और शंक्वाकार फ्लास्क', 'ಪಿಪೆಟ್ (10 mL) ಮತ್ತು ಶಂಕುವಿನಾಕಾರದ ಫ್ಲಾಸ್ಕ್')
    TILE = W('White tile and funnel', 'सफ़ेद टाइल और कीप', 'ಬಿಳಿ ಟೈಲ್ ಮತ್ತು ಆಲಿಕೆ')
    P_RINSE = W('Rinse the burette with the solution it will hold, and the pipette with the solution it will measure.', 'ब्यूरेट को उसी विलयन से धोएँ जो उसमें भरना है, और पिपेट को उसी से जिसे वह मापेगी।', 'ಬ್ಯೂರೆಟನ್ನು ಅದರಲ್ಲಿ ತುಂಬುವ ದ್ರಾವಣದಿಂದ, ಪಿಪೆಟನ್ನು ಅದು ಅಳೆಯುವ ದ್ರಾವಣದಿಂದ ತೊಳೆಯಿರಿ.')
    P_BUBBLE = W('Remove air bubbles from the burette nozzle and read the lower meniscus at eye level.', 'ब्यूरेट की नोक से वायु बुलबुले निकालें और निचला नवचंद्रक आँख के स्तर पर पढ़ें।', 'ಬ್ಯೂರೆಟ್ ನಳಿಕೆಯಿಂದ ಗಾಳಿ ಗುಳ್ಳೆ ತೆಗೆದು ಕೆಳಗಿನ ಮೆನಿಸ್ಕಸನ್ನು ಕಣ್ಣಿನ ಮಟ್ಟದಲ್ಲಿ ಓದಿ.')
    P_DROP = W('Near the end point add the titrant drop by drop, swirling the flask.', 'अंतिम बिंदु के पास अनुमापक बूँद-बूँद डालें और फ्लास्क घुमाते रहें।', 'ಅಂತ್ಯ ಬಿಂದುವಿನ ಹತ್ತಿರ ಅನುಮಾಪಕವನ್ನು ಹನಿ ಹನಿಯಾಗಿ ಸೇರಿಸಿ, ಫ್ಲಾಸ್ಕ್ ತಿರುಗಿಸುತ್ತಿರಿ.')
    P_CONC = W('Take at least three concordant readings (within 0.1 mL).', 'कम से कम तीन सहमत पाठ्यांक लें (0.1 mL के भीतर)।', 'ಕನಿಷ್ಠ ಮೂರು ಹೊಂದಿಕೆಯ ಓದುಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಿ (0.1 mL ಒಳಗೆ).')
    GOGGLES = W('Wear safety goggles; acids and alkalis harm the eyes.', 'सुरक्षा चश्मा पहनें; अम्ल और क्षार आँखों को हानि पहुँचाते हैं।', 'ಸುರಕ್ಷಾ ಕನ್ನಡಕ ಧರಿಸಿ; ಆಮ್ಲ ಮತ್ತು ಕ್ಷಾರಗಳು ಕಣ್ಣಿಗೆ ಹಾನಿ ಮಾಡುತ್ತವೆ.')
    CSV = W('Export the readings as CSV and fit the straight lines.', 'पाठ्यांक CSV में निर्यात कर सीधी रेखाएँ फ़िट करें।', 'ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ ಸರಳರೇಖೆಗಳನ್ನು ಹೊಂದಿಸಿ.')
    TITR_STEPS = [
        W('Rinse and fill the burette; note the initial reading.', 'ब्यूरेट धोकर भरें; प्रारंभिक पाठ्यांक लिखें।', 'ಬ್ಯೂರೆಟ್ ತೊಳೆದು ತುಂಬಿ; ಆರಂಭಿಕ ಓದು ಬರೆಯಿರಿ.'),
        W('Pipette 10 mL of the solution into the conical flask (add the indicator or acid as needed).', 'शंक्वाकार फ्लास्क में 10 mL विलयन पिपेट से लें (आवश्यक हो तो सूचक या अम्ल मिलाएँ)।', 'ಶಂಕುವಿನಾಕಾರದ ಫ್ಲಾಸ್ಕ್‌ಗೆ ಪಿಪೆಟ್‌ನಿಂದ 10 mL ದ್ರಾವಣ ಹಾಕಿ (ಬೇಕಾದರೆ ಸೂಚಕ ಅಥವಾ ಆಮ್ಲ ಸೇರಿಸಿ).'),
        W('Run in the titrant, swirling, until one drop gives a permanent colour change. Record the final reading.', 'घुमाते हुए अनुमापक डालें जब तक एक बूँद से स्थायी रंग परिवर्तन न हो। अंतिम पाठ्यांक लिखें।', 'ತಿರುಗಿಸುತ್ತಾ ಅನುಮಾಪಕ ಸೇರಿಸಿ, ಒಂದು ಹನಿ ಶಾಶ್ವತ ಬಣ್ಣ ಬದಲಾವಣೆ ತರುವವರೆಗೆ. ಅಂತಿಮ ಓದು ದಾಖಲಿಸಿ.'),
        W('Repeat until three readings agree within 0.1 mL.', 'तीन पाठ्यांक 0.1 mL के भीतर मेल खाने तक दोहराएँ।', 'ಮೂರು ಓದುಗಳು 0.1 mL ಒಳಗೆ ಹೊಂದುವವರೆಗೆ ಪುನರಾವರ್ತಿಸಿ.'),
        W('Use the mean titre and the mole ratio to find the unknown molarity.', 'माध्य अनुमापांक और मोल अनुपात से अज्ञात मोलरता ज्ञात करें।', 'ಸರಾಸರಿ ಅನುಮಾಪನಾಂಕ ಮತ್ತು ಮೋಲ್ ಅನುಪಾತದಿಂದ ಅಜ್ಞಾತ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯಿರಿ.'),
    ]
    chem = dict(subject='Chemistry', domain='chemistry')

    lab(id='titration-oxalic-naoh', bench='titration', setup={'pair': 'oxalic-naoh'}, levels=[11], curricula=['cbse', 'ncert', 'ka-puc'], **chem,
        keywords=['titration', 'volumetric analysis', 'oxalic acid', 'sodium hydroxide', 'phenolphthalein', 'molarity', 'acid base titration'],
        title=W('Standardising NaOH with oxalic acid', 'ऑक्ज़ैलिक अम्ल से NaOH का मानकीकरण', 'ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲದಿಂದ NaOH ಪ್ರಮಾಣೀಕರಣ'),
        summary=W('Titrate sodium hydroxide against standard oxalic acid with phenolphthalein and find its molarity.', 'फ़िनॉल्फ़्थेलिन के साथ सोडियम हाइड्रॉक्साइड का मानक ऑक्ज़ैलिक अम्ल से अनुमापन करें और उसकी मोलरता ज्ञात करें।', 'ಫೀನಾಲ್ಫ್ತಲೀನ್ ಬಳಸಿ ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡನ್ನು ಪ್ರಮಾಣಿತ ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲದ ವಿರುದ್ಧ ಅನುಮಾಪನ ಮಾಡಿ ಅದರ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To find the molarity of a given sodium hydroxide solution by titrating it against 0.05 M oxalic acid.', '0.05 M ऑक्ज़ैलिक अम्ल से अनुमापन करके दिए गए सोडियम हाइड्रॉक्साइड विलयन की मोलरता ज्ञात करना।', '0.05 M ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲದ ವಿರುದ್ಧ ಅನುಮಾಪನ ಮಾಡಿ ಕೊಟ್ಟ ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್ ದ್ರಾವಣದ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Oxalic acid is a dibasic acid: (COOH)₂ + 2NaOH → (COONa)₂ + 2H₂O. At the end point phenolphthalein turns from colourless to light pink. Moles of NaOH = 2 × moles of oxalic acid, so M(NaOH) = 2 × 0.05 × 10 ÷ titre.', 'ऑक्ज़ैलिक अम्ल द्विक्षारकी अम्ल है: (COOH)₂ + 2NaOH → (COONa)₂ + 2H₂O. अंतिम बिंदु पर फ़िनॉल्फ़्थेलिन रंगहीन से हल्का गुलाबी हो जाता है। NaOH के मोल = 2 × ऑक्ज़ैलिक अम्ल के मोल, अतः M(NaOH) = 2 × 0.05 × 10 ÷ अनुमापांक।', 'ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲ ದ್ವಿಕ್ಷಾರಕ ಆಮ್ಲ: (COOH)₂ + 2NaOH → (COONa)₂ + 2H₂O. ಅಂತ್ಯ ಬಿಂದುವಿನಲ್ಲಿ ಫೀನಾಲ್ಫ್ತಲೀನ್ ಬಣ್ಣರಹಿತದಿಂದ ತಿಳಿ ಗುಲಾಬಿಯಾಗುತ್ತದೆ. NaOH ಮೋಲ್ = 2 × ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲದ ಮೋಲ್; ಆದ್ದರಿಂದ M(NaOH) = 2 × 0.05 × 10 ÷ ಅನುಮಾಪನಾಂಕ.'),
        apparatus=[BURETTE, PIPETTE, TILE, W('0.05 M oxalic acid and phenolphthalein', '0.05 M ऑक्ज़ैलिक अम्ल और फ़िनॉल्फ़्थेलिन', '0.05 M ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲ ಮತ್ತು ಫೀನಾಲ್ಫ್ತಲೀನ್'), W('Sodium hydroxide solution (unknown)', 'सोडियम हाइड्रॉक्साइड विलयन (अज्ञात)', 'ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್ ದ್ರಾವಣ (ಅಜ್ಞಾತ)')],
        steps=TITR_STEPS, precautions=[P_RINSE, P_BUBBLE, P_DROP, P_CONC],
        conclusion=W('Concordant titres give the molarity of the sodium hydroxide; the end point is the first permanent light pink.', 'सहमत अनुमापांक सोडियम हाइड्रॉक्साइड की मोलरता देते हैं; अंतिम बिंदु पहला स्थायी हल्का गुलाबी रंग है।', 'ಹೊಂದಿಕೆಯ ಅನುಮಾಪನಾಂಕಗಳು ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್‌ನ ಮೋಲಾರಿಟಿ ನೀಡುತ್ತವೆ; ಅಂತ್ಯ ಬಿಂದು ಮೊದಲ ಶಾಶ್ವತ ತಿಳಿ ಗುಲಾಬಿ.'),
        viva=[Q(W('Why is NaOH not a primary standard?', 'NaOH प्राथमिक मानक क्यों नहीं है?', 'NaOH ಪ್ರಾಥಮಿಕ ಮಾನಕ ಏಕೆ ಅಲ್ಲ?'), W('It absorbs moisture and carbon dioxide from the air, so its mass is not exact.', 'यह वायु से नमी और कार्बन डाइऑक्साइड सोखता है, इसलिए उसका द्रव्यमान सटीक नहीं रहता।', 'ಅದು ಗಾಳಿಯಿಂದ ತೇವಾಂಶ ಮತ್ತು ಕಾರ್ಬನ್ ಡೈಆಕ್ಸೈಡ್ ಹೀರುತ್ತದೆ; ಆದ್ದರಿಂದ ಅದರ ದ್ರವ್ಯರಾಶಿ ನಿಖರವಲ್ಲ.')),
              Q(W('Why is phenolphthalein used and not methyl orange?', 'मेथिल ऑरेंज के स्थान पर फ़िनॉल्फ़्थेलिन क्यों?', 'ಮೀಥೈಲ್ ಆರೆಂಜ್ ಬದಲು ಫೀನಾಲ್ಫ್ತಲೀನ್ ಏಕೆ?'), W('Oxalic acid is weak: the pH jump at the end point lies in the basic range where phenolphthalein changes.', 'ऑक्ज़ैलिक अम्ल दुर्बल है: अंतिम बिंदु पर pH उछाल क्षारीय परास में है जहाँ फ़िनॉल्फ़्थेलिन बदलता है।', 'ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲ ದುರ್ಬಲ: ಅಂತ್ಯ ಬಿಂದುವಿನ pH ಜಿಗಿತ ಕ್ಷಾರೀಯ ವ್ಯಾಪ್ತಿಯಲ್ಲಿದೆ, ಅಲ್ಲಿ ಫೀನಾಲ್ಫ್ತಲೀನ್ ಬದಲಾಗುತ್ತದೆ.')),
              Q(W('What is the molar mass of hydrated oxalic acid?', 'जलयोजित ऑक्ज़ैलिक अम्ल का मोलर द्रव्यमान क्या है?', 'ಜಲಯುಕ್ತ ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲದ ಮೋಲಾರ್ ದ್ರವ್ಯರಾಶಿ ಎಷ್ಟು?'), W('126 g/mol ((COOH)₂·2H₂O).', '126 g/mol ((COOH)₂·2H₂O, जल के दो अणुओं सहित)।', '126 g/mol ((COOH)₂·2H₂O, ಎರಡು ನೀರಿನ ಅಣುಗಳೊಂದಿಗೆ).'))])

    lab(id='titration-hcl-naoh', bench='titration', setup={'pair': 'hcl-naoh'}, levels=[10, 11], curricula=['cbse', 'ncert', 'ka-sslc'], **chem,
        keywords=['titration', 'neutralisation', 'neutralization', 'hydrochloric acid', 'sodium hydroxide', 'acids bases and salts', 'indicator'],
        title=W('Strength of hydrochloric acid by titration', 'अनुमापन द्वारा हाइड्रोक्लोरिक अम्ल की प्रबलता', 'ಅನುಮಾಪನದಿಂದ ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲದ ಪ್ರಬಲತೆ'),
        summary=W('Neutralise samples of hydrochloric acid with 0.1 M NaOH; try both indicators and find each sample’s molarity.', 'हाइड्रोक्लोरिक अम्ल के नमूनों को 0.1 M NaOH से उदासीन करें; दोनों सूचक आज़माएँ और हर नमूने की मोलरता ज्ञात करें।', 'ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲದ ಮಾದರಿಗಳನ್ನು 0.1 M NaOH ನಿಂದ ತಟಸ್ಥಗೊಳಿಸಿ; ಎರಡೂ ಸೂಚಕಗಳನ್ನು ಪ್ರಯತ್ನಿಸಿ ಪ್ರತಿ ಮಾದರಿಯ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To find the molarity of hydrochloric acid by titrating it with 0.1 M sodium hydroxide.', '0.1 M सोडियम हाइड्रॉक्साइड से अनुमापन करके हाइड्रोक्लोरिक अम्ल की मोलरता ज्ञात करना।', '0.1 M ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್‌ನಿಂದ ಅನುಮಾಪನ ಮಾಡಿ ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲದ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('HCl + NaOH → NaCl + H₂O, one mole to one. For a strong acid and strong base the pH jumps from about 4 to 10 at the end point, so phenolphthalein and methyl orange both work. M₁V₁ = M₂V₂.', 'HCl + NaOH → NaCl + H₂O, एक मोल से एक मोल। प्रबल अम्ल और प्रबल क्षार के लिए अंतिम बिंदु पर pH लगभग 4 से 10 तक उछलता है, इसलिए फ़िनॉल्फ़्थेलिन और मेथिल ऑरेंज दोनों काम करते हैं। M₁V₁ = M₂V₂.', 'HCl + NaOH → NaCl + H₂O, ಒಂದು ಮೋಲ್‌ಗೆ ಒಂದು. ಪ್ರಬಲ ಆಮ್ಲ ಮತ್ತು ಪ್ರಬಲ ಕ್ಷಾರಕ್ಕೆ ಅಂತ್ಯ ಬಿಂದುವಿನಲ್ಲಿ pH ಸುಮಾರು 4 ರಿಂದ 10 ಕ್ಕೆ ಜಿಗಿಯುತ್ತದೆ; ಆದ್ದರಿಂದ ಫೀನಾಲ್ಫ್ತಲೀನ್ ಮತ್ತು ಮೀಥೈಲ್ ಆರೆಂಜ್ ಎರಡೂ ಕೆಲಸ ಮಾಡುತ್ತವೆ. M₁V₁ = M₂V₂.'),
        apparatus=[BURETTE, PIPETTE, TILE, W('0.1 M NaOH; phenolphthalein and methyl orange', '0.1 M NaOH; फ़िनॉल्फ़्थेलिन और मेथिल ऑरेंज', '0.1 M NaOH; ಫೀನಾಲ್ಫ್ತಲೀನ್ ಮತ್ತು ಮೀಥೈಲ್ ಆರೆಂಜ್'), W('Hydrochloric acid samples A, B, C', 'हाइड्रोक्लोरिक अम्ल के नमूने A, B, C', 'ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲ ಮಾದರಿಗಳು A, B, C')],
        steps=TITR_STEPS, precautions=[P_RINSE, P_BUBBLE, P_DROP, GOGGLES],
        conclusion=W('Each sample’s molarity follows from M₁V₁ = M₂V₂; both indicators give the same end point for a strong acid and strong base.', 'हर नमूने की मोलरता M₁V₁ = M₂V₂ से मिलती है; प्रबल अम्ल-प्रबल क्षार के लिए दोनों सूचक एक ही अंतिम बिंदु देते हैं।', 'ಪ್ರತಿ ಮಾದರಿಯ ಮೋಲಾರಿಟಿ M₁V₁ = M₂V₂ ನಿಂದ ಸಿಗುತ್ತದೆ; ಪ್ರಬಲ ಆಮ್ಲ-ಪ್ರಬಲ ಕ್ಷಾರಕ್ಕೆ ಎರಡೂ ಸೂಚಕಗಳು ಒಂದೇ ಅಂತ್ಯ ಬಿಂದು ನೀಡುತ್ತವೆ.'),
        viva=[Q(W('What is neutralisation?', 'उदासीनीकरण क्या है?', 'ತಟಸ್ಥೀಕರಣ ಎಂದರೇನು?'), W('The reaction of an acid and a base to form a salt and water.', 'अम्ल और क्षार की अभिक्रिया जिसमें लवण और जल बनते हैं।', 'ಆಮ್ಲ ಮತ್ತು ಕ್ಷಾರ ಪ್ರತಿಕ್ರಿಯಿಸಿ ಲವಣ ಮತ್ತು ನೀರು ಉಂಟಾಗುವುದು.')),
              Q(W('What is the pH at the end point here?', 'यहाँ अंतिम बिंदु पर pH कितना है?', 'ಇಲ್ಲಿ ಅಂತ್ಯ ಬಿಂದುವಿನ pH ಎಷ್ಟು?'), W('7: NaCl solution is neutral.', '7: NaCl विलयन उदासीन है।', '7: NaCl ದ್ರಾವಣ ತಟಸ್ಥ.')),
              Q(W('Why is a white tile placed under the flask?', 'फ्लास्क के नीचे सफ़ेद टाइल क्यों रखते हैं?', 'ಫ್ಲಾಸ್ಕ್ ಕೆಳಗೆ ಬಿಳಿ ಟೈಲ್ ಏಕೆ ಇಡುತ್ತಾರೆ?'), W('To see the first faint colour change clearly.', 'पहला हल्का रंग परिवर्तन साफ़ देखने के लिए।', 'ಮೊದಲ ಮಸುಕಾದ ಬಣ್ಣ ಬದಲಾವಣೆ ಸ್ಪಷ್ಟವಾಗಿ ಕಾಣಲು.'))])

    KMNO4_PRE = [P_RINSE, W('Read the upper meniscus of KMnO₄: it is too dark to see the lower one.', 'KMnO₄ का ऊपरी नवचंद्रक पढ़ें: निचला देखने के लिए यह बहुत गहरा है।', 'KMnO₄ ನ ಮೇಲಿನ ಮೆನಿಸ್ಕಸ್ ಓದಿ: ಕೆಳಗಿನದು ಕಾಣಲು ಅದು ತುಂಬ ಗಾಢ.'), P_DROP,
                 W('Add enough dilute H₂SO₄; never use HCl or HNO₃ to acidify.', 'पर्याप्त तनु H₂SO₄ डालें; अम्लीकरण के लिए HCl या HNO₃ कभी न लें।', 'ಸಾಕಷ್ಟು ವಿರಳ H₂SO₄ ಸೇರಿಸಿ; ಆಮ್ಲೀಕರಣಕ್ಕೆ HCl ಅಥವಾ HNO₃ ಎಂದೂ ಬಳಸಬೇಡಿ.')]
    KMNO4_VIVA = [Q(W('Why is no indicator needed?', 'सूचक की आवश्यकता क्यों नहीं?', 'ಸೂಚಕ ಏಕೆ ಬೇಕಿಲ್ಲ?'), W('KMnO₄ is its own indicator: the first excess drop turns the solution pink.', 'KMnO₄ स्वयं सूचक है: पहली अतिरिक्त बूँद विलयन को गुलाबी कर देती है।', 'KMnO₄ ತಾನೇ ಸೂಚಕ: ಮೊದಲ ಹೆಚ್ಚುವರಿ ಹನಿ ದ್ರಾವಣವನ್ನು ಗುಲಾಬಿಯಾಗಿಸುತ್ತದೆ.')),
                  Q(W('Why is HCl not used to acidify?', 'अम्लीकरण के लिए HCl क्यों नहीं?', 'ಆಮ್ಲೀಕರಣಕ್ಕೆ HCl ಏಕೆ ಅಲ್ಲ?'), W('KMnO₄ would oxidise chloride ions to chlorine, using up extra titrant.', 'KMnO₄ क्लोराइड आयनों को क्लोरीन में ऑक्सीकृत कर अतिरिक्त अनुमापक खपा देगा।', 'KMnO₄ ಕ್ಲೋರೈಡ್ ಅಯಾನುಗಳನ್ನು ಕ್ಲೋರಿನ್ ಆಗಿ ಉತ್ಕರ್ಷಿಸಿ ಹೆಚ್ಚುವರಿ ಅನುಮಾಪಕ ಬಳಸುತ್ತದೆ.')),
                  Q(W('What is the oxidation state of Mn in KMnO₄, and after the reaction?', 'KMnO₄ में और अभिक्रिया के बाद Mn की ऑक्सीकरण अवस्था क्या है?', 'KMnO₄ ನಲ್ಲಿ ಮತ್ತು ಪ್ರತಿಕ್ರಿಯೆಯ ನಂತರ Mn ನ ಉತ್ಕರ್ಷಣ ಸ್ಥಿತಿ ಏನು?'), W('+7, reduced to +2 (Mn²⁺) in acid.', '+7, अम्ल में +2 (Mn²⁺) तक अपचयित।', '+7, ಆಮ್ಲದಲ್ಲಿ +2 (Mn²⁺) ಗೆ ಅಪಕರ್ಷಿತ.'))]
    lab(id='kmno4-oxalic', bench='titration', setup={'pair': 'kmno4-oxalic'}, levels=[12], curricula=['cbse', 'ncert', 'ka-puc'], **chem,
        keywords=['redox titration', 'potassium permanganate', 'kmno4', 'oxalic acid', 'volumetric analysis', 'self indicator'],
        title=W('KMnO₄ against oxalic acid (redox titration)', 'ऑक्ज़ैलिक अम्ल से KMnO₄ का अनुमापन (रेडॉक्स)', 'ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲದ ವಿರುದ್ಧ KMnO₄ (ರೆಡಾಕ್ಸ್ ಅನುಮಾಪನ)'),
        summary=W('Titrate hot acidified oxalic acid with potassium permanganate until a permanent pink appears.', 'गरम अम्लीकृत ऑक्ज़ैलिक अम्ल का पोटैशियम परमैंगनेट से तब तक अनुमापन करें जब तक स्थायी गुलाबी रंग न आए।', 'ಬಿಸಿ ಆಮ್ಲೀಕೃತ ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲವನ್ನು ಶಾಶ್ವತ ಗುಲಾಬಿ ಬರುವವರೆಗೆ ಪೊಟ್ಯಾಸಿಯಂ ಪರ್ಮ್ಯಾಂಗನೇಟ್‌ನಿಂದ ಅನುಮಾಪನ ಮಾಡಿ.'),
        aim=W('To find the molarity of a KMnO₄ solution by titrating it against 0.05 M oxalic acid.', '0.05 M ऑक्ज़ैलिक अम्ल से अनुमापन करके KMnO₄ विलयन की मोलरता ज्ञात करना।', '0.05 M ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲದ ವಿರುದ್ಧ ಅನುಮಾಪನ ಮಾಡಿ KMnO₄ ದ್ರಾವಣದ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('In acid, 2MnO₄⁻ + 5C₂O₄²⁻ + 16H⁺ → 2Mn²⁺ + 10CO₂ + 8H₂O. The flask is warmed to 60–70 °C to speed the reaction. So M(KMnO₄) = (2/5) × 0.05 × 10 ÷ titre.', 'अम्ल में 2MnO₄⁻ + 5C₂O₄²⁻ + 16H⁺ → 2Mn²⁺ + 10CO₂ + 8H₂O. अभिक्रिया तेज़ करने के लिए फ्लास्क 60–70 °C तक गरम किया जाता है। अतः M(KMnO₄) = (2/5) × 0.05 × 10 ÷ अनुमापांक।', 'ಆಮ್ಲದಲ್ಲಿ 2MnO₄⁻ + 5C₂O₄²⁻ + 16H⁺ → 2Mn²⁺ + 10CO₂ + 8H₂O. ಪ್ರತಿಕ್ರಿಯೆ ವೇಗಗೊಳಿಸಲು ಫ್ಲಾಸ್ಕನ್ನು 60–70 °C ಗೆ ಬಿಸಿಮಾಡುತ್ತಾರೆ. ಆದ್ದರಿಂದ M(KMnO₄) = (2/5) × 0.05 × 10 ÷ ಅನುಮಾಪನಾಂಕ.'),
        apparatus=[BURETTE, PIPETTE, W('0.05 M oxalic acid and dilute H₂SO₄', '0.05 M ऑक्ज़ैलिक अम्ल और तनु H₂SO₄', '0.05 M ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲ ಮತ್ತು ವಿರಳ H₂SO₄'), W('KMnO₄ solution (unknown)', 'KMnO₄ विलयन (अज्ञात)', 'KMnO₄ ದ್ರಾವಣ (ಅಜ್ಞಾತ)'), W('Burner, wire gauze and thermometer', 'बर्नर, तार की जाली और तापमापी', 'ಬರ್ನರ್, ತಂತಿ ಜಾಲರಿ ಮತ್ತು ತಾಪಮಾಪಕ')],
        steps=TITR_STEPS, precautions=KMNO4_PRE,
        conclusion=W('The first permanent pink marks the end point; the mean titre gives the molarity of KMnO₄ through the 2 : 5 mole ratio.', 'पहला स्थायी गुलाबी रंग अंतिम बिंदु है; माध्य अनुमापांक 2 : 5 मोल अनुपात से KMnO₄ की मोलरता देता है।', 'ಮೊದಲ ಶಾಶ್ವತ ಗುಲಾಬಿ ಅಂತ್ಯ ಬಿಂದು; ಸರಾಸರಿ ಅನುಮಾಪನಾಂಕ 2 : 5 ಮೋಲ್ ಅನುಪಾತದ ಮೂಲಕ KMnO₄ ನ ಮೋಲಾರಿಟಿ ನೀಡುತ್ತದೆ.'),
        viva=KMNO4_VIVA + [Q(W('Why is the oxalic acid heated?', 'ऑक्ज़ैलिक अम्ल को गरम क्यों करते हैं?', 'ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲವನ್ನು ಏಕೆ ಬಿಸಿಮಾಡುತ್ತಾರೆ?'), W('The reaction is slow at room temperature; Mn²⁺ formed later catalyses it.', 'कमरे के ताप पर अभिक्रिया धीमी है; बाद में बना Mn²⁺ उसे उत्प्रेरित करता है।', 'ಕೋಣೆಯ ತಾಪದಲ್ಲಿ ಪ್ರತಿಕ್ರಿಯೆ ನಿಧಾನ; ನಂತರ ಉಂಟಾದ Mn²⁺ ಅದನ್ನು ವೇಗವರ್ಧಿಸುತ್ತದೆ.'))])

    lab(id='kmno4-mohr', bench='titration', setup={'pair': 'kmno4-mohr'}, levels=[12], curricula=['cbse', 'ncert', 'ka-puc'], **chem,
        keywords=['redox titration', 'potassium permanganate', "mohr's salt", 'ferrous ammonium sulphate', 'volumetric analysis'],
        title=W("KMnO₄ against Mohr's salt (redox titration)", 'मोर लवण से KMnO₄ का अनुमापन (रेडॉक्स)', 'ಮೋರ್ ಲವಣದ ವಿರುದ್ಧ KMnO₄ (ರೆಡಾಕ್ಸ್ ಅನುಮಾಪನ)'),
        summary=W("Titrate acidified Mohr's salt with potassium permanganate at room temperature.", 'कमरे के ताप पर अम्लीकृत मोर लवण का पोटैशियम परमैंगनेट से अनुमापन करें।', 'ಕೋಣೆಯ ತಾಪದಲ್ಲಿ ಆಮ್ಲೀಕೃತ ಮೋರ್ ಲವಣವನ್ನು ಪೊಟ್ಯಾಸಿಯಂ ಪರ್ಮ್ಯಾಂಗನೇಟ್‌ನಿಂದ ಅನುಮಾಪನ ಮಾಡಿ.'),
        aim=W("To find the molarity of KMnO₄ by titrating it against 0.1 M Mohr's salt (ferrous ammonium sulphate).", '0.1 M मोर लवण (फ़ेरस अमोनियम सल्फ़ेट) से अनुमापन करके KMnO₄ की मोलरता ज्ञात करना।', '0.1 M ಮೋರ್ ಲವಣದ (ಫೆರಸ್ ಅಮೋನಿಯಂ ಸಲ್ಫೇಟ್) ವಿರುದ್ಧ ಅನುಮಾಪನ ಮಾಡಿ KMnO₄ ನ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O. One permanganate oxidises five iron(II) ions, so M(KMnO₄) = 0.1 × 10 ÷ (5 × titre). Heating is not needed: it would oxidise Fe²⁺ in air.', 'MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O. एक परमैंगनेट पाँच आयरन(II) आयनों को ऑक्सीकृत करता है, अतः M(KMnO₄) = 0.1 × 10 ÷ (5 × अनुमापांक)। गरम करना नहीं चाहिए: इससे Fe²⁺ वायु में ऑक्सीकृत हो जाएगा।', 'MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O. ಒಂದು ಪರ್ಮ್ಯಾಂಗನೇಟ್ ಐದು ಕಬ್ಬಿಣ(II) ಅಯಾನುಗಳನ್ನು ಉತ್ಕರ್ಷಿಸುತ್ತದೆ; ಆದ್ದರಿಂದ M(KMnO₄) = 0.1 × 10 ÷ (5 × ಅನುಮಾಪನಾಂಕ). ಬಿಸಿಮಾಡಬಾರದು: ಅದು ಗಾಳಿಯಲ್ಲಿ Fe²⁺ ಅನ್ನು ಉತ್ಕರ್ಷಿಸುತ್ತದೆ.'),
        apparatus=[BURETTE, PIPETTE, W("0.1 M Mohr's salt and dilute H₂SO₄", '0.1 M मोर लवण और तनु H₂SO₄', '0.1 M ಮೋರ್ ಲವಣ ಮತ್ತು ವಿರಳ H₂SO₄'), W('KMnO₄ solution (unknown)', 'KMnO₄ विलयन (अज्ञात)', 'KMnO₄ ದ್ರಾವಣ (ಅಜ್ಞಾತ)'), TILE],
        steps=TITR_STEPS, precautions=KMNO4_PRE,
        conclusion=W("Five Fe²⁺ react with each MnO₄⁻; the concordant titre gives the molarity of the permanganate.", 'हर MnO₄⁻ से पाँच Fe²⁺ अभिक्रिया करते हैं; सहमत अनुमापांक परमैंगनेट की मोलरता देता है।', 'ಪ್ರತಿ MnO₄⁻ ಗೆ ಐದು Fe²⁺ ಪ್ರತಿಕ್ರಿಯಿಸುತ್ತವೆ; ಹೊಂದಿಕೆಯ ಅನುಮಾಪನಾಂಕ ಪರ್ಮ್ಯಾಂಗನೇಟ್‌ನ ಮೋಲಾರಿಟಿ ನೀಡುತ್ತದೆ.'),
        viva=KMNO4_VIVA + [Q(W("Why is Mohr's salt preferred to ferrous sulphate?", 'फ़ेरस सल्फ़ेट की तुलना में मोर लवण क्यों अच्छा है?', 'ಫೆರಸ್ ಸಲ್ಫೇಟ್‌ಗಿಂತ ಮೋರ್ ಲವಣ ಏಕೆ ಉತ್ತಮ?'), W('It is a stable double salt that is not readily oxidised by air, so it can be weighed as a standard.', 'यह स्थिर द्विक लवण है जो वायु से जल्दी ऑक्सीकृत नहीं होता, इसलिए मानक के रूप में तौला जा सकता है।', 'ಅದು ಗಾಳಿಯಿಂದ ಬೇಗ ಉತ್ಕರ್ಷಣಗೊಳ್ಳದ ಸ್ಥಿರ ದ್ವಿ ಲವಣ; ಆದ್ದರಿಂದ ಮಾನಕವಾಗಿ ತೂಕ ಮಾಡಬಹುದು.'))])

    ug = dict(levels=['ug'], curricula=['ug-chemistry'], **chem)
    lab(id='ph-metric-titration', bench='ph-titration', **ug,
        keywords=['potentiometric titration', 'ph metric titration', 'ph meter', 'weak acid', 'pka', 'acetic acid', 'buffer'],
        title=W('pH-metric titration of acetic acid', 'ऐसीटिक अम्ल का pH-मितीय अनुमापन', 'ಅಸಿಟಿಕ್ ಆಮ್ಲದ pH-ಮಾಪಕ ಅನುಮಾಪನ'),
        summary=W('Follow the pH as NaOH is added; find the end point from the steepest rise and pKa at half-neutralisation.', 'NaOH डालते हुए pH देखें; सबसे खड़े उभार से अंतिम बिंदु और अर्ध-उदासीनीकरण पर pKa ज्ञात करें।', 'NaOH ಸೇರಿಸುತ್ತಾ pH ಗಮನಿಸಿ; ಅತಿ ಕಡಿದಾದ ಏರಿಕೆಯಿಂದ ಅಂತ್ಯ ಬಿಂದು ಮತ್ತು ಅರ್ಧ-ತಟಸ್ಥೀಕರಣದಲ್ಲಿ pKa ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To titrate acetic acid with NaOH using a pH meter and find its concentration and dissociation constant.', 'pH मीटर से ऐसीटिक अम्ल का NaOH से अनुमापन कर उसकी सांद्रता और वियोजन नियतांक ज्ञात करना।', 'pH ಮಾಪಕ ಬಳಸಿ ಅಸಿಟಿಕ್ ಆಮ್ಲವನ್ನು NaOH ನಿಂದ ಅನುಮಾಪನ ಮಾಡಿ ಅದರ ಸಾಂದ್ರತೆ ಮತ್ತು ವಿಯೋಜನ ಸ್ಥಿರಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('The glass electrode’s EMF changes by 59 mV per pH unit. During the titration a buffer of CH₃COOH and CH₃COO⁻ forms; by the Henderson equation pH = pKa + log([A⁻]/[HA]), so at half-neutralisation pH = pKa. At equivalence the pH jumps most steeply (largest ΔpH/ΔV).', 'काँच इलेक्ट्रोड का EMF प्रति pH इकाई 59 mV बदलता है। अनुमापन में CH₃COOH और CH₃COO⁻ का बफ़र बनता है; हेंडरसन समीकरण pH = pKa + log([A⁻]/[HA]) से अर्ध-उदासीनीकरण पर pH = pKa. तुल्यता पर pH सबसे तेज़ी से उछलता है (सबसे बड़ा ΔpH/ΔV)।', 'ಗಾಜಿನ ವಿದ್ಯುದ್ವಾರದ EMF ಪ್ರತಿ pH ಏಕಮಾನಕ್ಕೆ 59 mV ಬದಲಾಗುತ್ತದೆ. ಅನುಮಾಪನದಲ್ಲಿ CH₃COOH ಮತ್ತು CH₃COO⁻ ಬಫರ್ ರೂಪುಗೊಳ್ಳುತ್ತದೆ; ಹೆಂಡರ್ಸನ್ ಸಮೀಕರಣ pH = pKa + log([A⁻]/[HA]) ಪ್ರಕಾರ ಅರ್ಧ-ತಟಸ್ಥೀಕರಣದಲ್ಲಿ pH = pKa. ಸಮತುಲ್ಯತೆಯಲ್ಲಿ pH ಅತಿ ಕಡಿದಾಗಿ ಜಿಗಿಯುತ್ತದೆ (ಅತಿ ದೊಡ್ಡ ΔpH/ΔV).'),
        apparatus=[W('pH meter with combined glass electrode', 'संयुक्त काँच इलेक्ट्रोड सहित pH मीटर', 'ಸಂಯುಕ್ತ ಗಾಜಿನ ವಿದ್ಯುದ್ವಾರ ಸಹಿತ pH ಮಾಪಕ'), W('Buffer solutions of pH 4 and 9.2', 'pH 4 और 9.2 के बफ़र विलयन', 'pH 4 ಮತ್ತು 9.2 ರ ಬಫರ್ ದ್ರಾವಣಗಳು'), BURETTE, W('Beaker and magnetic stirrer', 'बीकर और चुंबकीय विलोडक', 'ಬೀಕರ್ ಮತ್ತು ಕಾಂತೀಯ ಕಲಕಿ')],
        steps=[W('Calibrate the pH meter with the two buffers.', 'दोनों बफ़रों से pH मीटर का अंशांकन करें।', 'ಎರಡು ಬಫರ್‌ಗಳಿಂದ pH ಮಾಪಕವನ್ನು ಮಾಪನಾಂಕಗೊಳಿಸಿ.'),
               W('Take 25 mL of acetic acid in the beaker with the electrode dipping in.', 'बीकर में 25 mL ऐसीटिक अम्ल लें जिसमें इलेक्ट्रोड डूबा हो।', 'ವಿದ್ಯುದ್ವಾರ ಮುಳುಗಿರುವ ಬೀಕರ್‌ನಲ್ಲಿ 25 mL ಅಸಿಟಿಕ್ ಆಮ್ಲ ತೆಗೆದುಕೊಳ್ಳಿ.'),
               W('Add NaOH 1 mL at a time (0.2 mL near the end point), stirring, and record the pH.', 'हिलाते हुए एक बार में 1 mL NaOH डालें (अंतिम बिंदु के पास 0.2 mL), और pH लिखें।', 'ಕಲಕುತ್ತಾ ಒಮ್ಮೆಗೆ 1 mL NaOH ಸೇರಿಸಿ (ಅಂತ್ಯ ಬಿಂದುವಿನ ಹತ್ತಿರ 0.2 mL), pH ದಾಖಲಿಸಿ.'),
               W('Plot pH against V and ΔpH/ΔV against V; locate the equivalence point.', 'pH और V तथा ΔpH/ΔV और V के ग्राफ़ बनाएँ; तुल्यता बिंदु ढूँढें।', 'pH ಮತ್ತು V ಹಾಗೂ ΔpH/ΔV ಮತ್ತು V ನಕ್ಷೆಗಳನ್ನು ಎಳೆದು ಸಮತುಲ್ಯ ಬಿಂದು ಹುಡುಕಿ.'),
               W('Read pH at half the equivalence volume: that is pKa.', 'तुल्यता आयतन के आधे पर pH पढ़ें: वही pKa है।', 'ಸಮತುಲ್ಯ ಘನಫಲದ ಅರ್ಧದಲ್ಲಿ pH ಓದಿ: ಅದೇ pKa.'), CSV],
        precautions=[W('Rinse the electrode with distilled water between solutions and never let it dry.', 'विलयनों के बीच इलेक्ट्रोड को आसुत जल से धोएँ और उसे कभी सूखने न दें।', 'ದ್ರಾವಣಗಳ ನಡುವೆ ವಿದ್ಯುದ್ವಾರವನ್ನು ಬಟ್ಟಿ ನೀರಿನಿಂದ ತೊಳೆಯಿರಿ, ಎಂದೂ ಒಣಗಲು ಬಿಡಬೇಡಿ.'), W('Wait for the reading to settle after each addition.', 'हर बार डालने के बाद पाठ्यांक स्थिर होने की प्रतीक्षा करें।', 'ಪ್ರತಿ ಸೇರ್ಪಡೆಯ ನಂತರ ಓದು ಸ್ಥಿರವಾಗಲು ಕಾಯಿರಿ.'), W('Keep the electrode clear of the stirrer bar.', 'इलेक्ट्रोड को विलोडक छड़ से दूर रखें।', 'ವಿದ್ಯುದ್ವಾರವನ್ನು ಕಲಕುವ ಸರಳಿನಿಂದ ದೂರವಿಡಿ.')],
        conclusion=W('The curve rises slowly through the buffer region and steeply at equivalence (pH ≈ 8.7, basic because acetate hydrolyses); the half-neutralisation pH gives pKa ≈ 4.74.', 'वक्र बफ़र क्षेत्र में धीरे और तुल्यता पर तेज़ी से उठता है (pH ≈ 8.7, क्षारीय क्योंकि ऐसीटेट जल-अपघटित होता है); अर्ध-उदासीनीकरण का pH, pKa ≈ 4.74 देता है।', 'ವಕ್ರ ಬಫರ್ ಪ್ರದೇಶದಲ್ಲಿ ನಿಧಾನವಾಗಿ, ಸಮತುಲ್ಯತೆಯಲ್ಲಿ ಕಡಿದಾಗಿ ಏರುತ್ತದೆ (pH ≈ 8.7, ಅಸಿಟೇಟ್ ಜಲವಿಭಜನೆಯಿಂದ ಕ್ಷಾರೀಯ); ಅರ್ಧ-ತಟಸ್ಥೀಕರಣದ pH, pKa ≈ 4.74 ನೀಡುತ್ತದೆ.'),
        viva=[Q(W('Why is the pH at equivalence above 7?', 'तुल्यता पर pH 7 से अधिक क्यों है?', 'ಸಮತುಲ್ಯತೆಯಲ್ಲಿ pH 7 ಕ್ಕಿಂತ ಹೆಚ್ಚು ಏಕೆ?'), W('Sodium acetate hydrolyses: CH₃COO⁻ + H₂O ⇌ CH₃COOH + OH⁻.', 'सोडियम ऐसीटेट जल-अपघटित होता है: CH₃COO⁻ + H₂O ⇌ CH₃COOH + OH⁻.', 'ಸೋಡಿಯಂ ಅಸಿಟೇಟ್ ಜಲವಿಭಜನೆಯಾಗುತ್ತದೆ: CH₃COO⁻ + H₂O ⇌ CH₃COOH + OH⁻.')),
              Q(W('What is a buffer?', 'बफ़र क्या है?', 'ಬಫರ್ ಎಂದರೇನು?'), W('A solution that resists change of pH when a little acid or base is added.', 'ऐसा विलयन जो थोड़ा अम्ल या क्षार डालने पर pH परिवर्तन का विरोध करता है।', 'ಸ್ವಲ್ಪ ಆಮ್ಲ ಅಥವಾ ಕ್ಷಾರ ಸೇರಿಸಿದಾಗ pH ಬದಲಾವಣೆಯನ್ನು ವಿರೋಧಿಸುವ ದ್ರಾವಣ.')),
              Q(W('Why calibrate with two buffers?', 'दो बफ़रों से अंशांकन क्यों?', 'ಎರಡು ಬಫರ್‌ಗಳಿಂದ ಮಾಪನಾಂಕ ಏಕೆ?'), W('To set both the offset and the slope (mV per pH) of the electrode.', 'इलेक्ट्रोड का ऑफ़सेट और प्रवणता (mV प्रति pH) दोनों तय करने के लिए।', 'ವಿದ್ಯುದ್ವಾರದ ಆಫ್‌ಸೆಟ್ ಮತ್ತು ಇಳಿಜಾರು (ಪ್ರತಿ pH ಗೆ mV) ಎರಡನ್ನೂ ಹೊಂದಿಸಲು.'))])

    lab(id='conductometric-titration', bench='conductometric', **ug,
        keywords=['conductometric titration', 'conductance', 'conductivity', 'strong acid', 'weak acid', 'electrochemistry'],
        title=W('Conductometric titration of acids with NaOH', 'NaOH से अम्लों का चालकतामितीय अनुमापन', 'NaOH ನಿಂದ ಆಮ್ಲಗಳ ವಾಹಕತಾಮಾಪಕ ಅನುಮಾಪನ'),
        summary=W('Follow the conductance as NaOH neutralises HCl or acetic acid; the two straight parts meet at the end point.', 'NaOH द्वारा HCl या ऐसीटिक अम्ल के उदासीनीकरण में चालकता देखें; दो सीधे भाग अंतिम बिंदु पर मिलते हैं।', 'NaOH, HCl ಅಥವಾ ಅಸಿಟಿಕ್ ಆಮ್ಲವನ್ನು ತಟಸ್ಥಗೊಳಿಸುವಾಗ ವಾಹಕತೆ ಗಮನಿಸಿ; ಎರಡು ನೇರ ಭಾಗಗಳು ಅಂತ್ಯ ಬಿಂದುವಿನಲ್ಲಿ ಸೇರುತ್ತವೆ.'),
        aim=W('To find the strength of a strong and a weak acid by conductometric titration with NaOH.', 'NaOH से चालकतामितीय अनुमापन द्वारा एक प्रबल और एक दुर्बल अम्ल की प्रबलता ज्ञात करना।', 'NaOH ನಿಂದ ವಾಹಕತಾಮಾಪಕ ಅನುಮಾಪನ ಮಾಡಿ ಒಂದು ಪ್ರಬಲ ಮತ್ತು ಒಂದು ದುರ್ಬಲ ಆಮ್ಲದ ಪ್ರಬಲತೆ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Conductance is the sum of λc for the ions present. Adding NaOH to HCl replaces fast H⁺ (λ = 350) by slow Na⁺ (50), so conductance falls; after the end point free OH⁻ (198) makes it rise: a V-shape. With acetic acid, conductance rises gently as acetate ions form and then more steeply after the end point. Readings are corrected for dilution.', 'चालकता उपस्थित आयनों के λc का योग है। HCl में NaOH डालने से तेज़ H⁺ (λ = 350) की जगह धीमा Na⁺ (50) आता है, इसलिए चालकता घटती है; अंतिम बिंदु के बाद मुक्त OH⁻ (198) उसे बढ़ाता है: V-आकार। ऐसीटिक अम्ल में ऐसीटेट आयन बनने से चालकता धीरे बढ़ती है और अंतिम बिंदु के बाद तेज़ी से। पाठ्यांक तनुता के लिए संशोधित किए जाते हैं।', 'ವಾಹಕತೆ ಇರುವ ಅಯಾನುಗಳ λc ಯ ಮೊತ್ತ. HCl ಗೆ NaOH ಸೇರಿಸಿದಾಗ ವೇಗದ H⁺ (λ = 350) ಬದಲು ನಿಧಾನ Na⁺ (50) ಬರುತ್ತದೆ, ವಾಹಕತೆ ಇಳಿಯುತ್ತದೆ; ಅಂತ್ಯ ಬಿಂದುವಿನ ನಂತರ ಮುಕ್ತ OH⁻ (198) ಅದನ್ನು ಏರಿಸುತ್ತದೆ: V-ಆಕಾರ. ಅಸಿಟಿಕ್ ಆಮ್ಲದಲ್ಲಿ ಅಸಿಟೇಟ್ ಅಯಾನುಗಳು ಬಂದಂತೆ ವಾಹಕತೆ ನಿಧಾನವಾಗಿ, ಅಂತ್ಯ ಬಿಂದುವಿನ ನಂತರ ಕಡಿದಾಗಿ ಏರುತ್ತದೆ. ಓದುಗಳನ್ನು ವಿರಳೀಕರಣಕ್ಕೆ ತಿದ್ದುತ್ತಾರೆ.'),
        apparatus=[W('Conductivity meter and cell', 'चालकता मीटर और सेल', 'ವಾಹಕತಾ ಮಾಪಕ ಮತ್ತು ಕೋಶ'), BURETTE, W('0.1 M NaOH; 0.01 M HCl and acetic acid', '0.1 M NaOH; 0.01 M HCl और ऐसीटिक अम्ल', '0.1 M NaOH; 0.01 M HCl ಮತ್ತು ಅಸಿಟಿಕ್ ಆಮ್ಲ'), W('Beaker and stirrer', 'बीकर और विलोडक', 'ಬೀಕರ್ ಮತ್ತು ಕಲಕಿ')],
        steps=[W('Put 100 mL of the acid in the beaker and dip the conductivity cell in it.', 'बीकर में 100 mL अम्ल लेकर उसमें चालकता सेल डुबाएँ।', 'ಬೀಕರ್‌ನಲ್ಲಿ 100 mL ಆಮ್ಲ ಹಾಕಿ ಅದರಲ್ಲಿ ವಾಹಕತಾ ಕೋಶ ಮುಳುಗಿಸಿ.'),
               W('Add NaOH 1 mL at a time, stir, and record the conductance.', 'एक बार में 1 mL NaOH डालें, हिलाएँ, और चालकता लिखें।', 'ಒಮ್ಮೆಗೆ 1 mL NaOH ಸೇರಿಸಿ, ಕಲಕಿ, ವಾಹಕತೆ ದಾಖಲಿಸಿ.'),
               W('Continue well past the turning point.', 'मोड़ बिंदु से काफ़ी आगे तक जारी रखें।', 'ತಿರುವು ಬಿಂದುವಿನ ಸಾಕಷ್ಟು ಆಚೆಯವರೆಗೆ ಮುಂದುವರಿಸಿ.'),
               W('Plot corrected conductance against V and draw the two straight lines; their meeting point is the end point.', 'संशोधित चालकता और V का ग्राफ़ बनाकर दो सीधी रेखाएँ खींचें; उनका मिलन बिंदु अंतिम बिंदु है।', 'ತಿದ್ದಿದ ವಾಹಕತೆ ಮತ್ತು V ನಕ್ಷೆ ಎಳೆದು ಎರಡು ಸರಳರೇಖೆಗಳನ್ನು ಎಳೆಯಿರಿ; ಅವು ಸೇರುವಲ್ಲಿ ಅಂತ್ಯ ಬಿಂದು.'),
               W('Repeat with acetic acid and compare the shapes.', 'ऐसीटिक अम्ल के साथ दोहराएँ और आकारों की तुलना करें।', 'ಅಸಿಟಿಕ್ ಆಮ್ಲದೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ ಆಕಾರಗಳನ್ನು ಹೋಲಿಸಿ.'), CSV],
        precautions=[W('Use a titrant about ten times stronger than the acid so that dilution is small.', 'अम्ल से लगभग दस गुना प्रबल अनुमापक लें ताकि तनुता कम हो।', 'ವಿರಳೀಕರಣ ಕಡಿಮೆಯಿರಲು ಆಮ್ಲಕ್ಕಿಂತ ಸುಮಾರು ಹತ್ತು ಪಟ್ಟು ಪ್ರಬಲ ಅನುಮಾಪಕ ಬಳಸಿ.'), W('Keep the temperature constant: conductance rises about 2% per °C.', 'ताप नियत रखें: चालकता लगभग 2% प्रति °C बढ़ती है।', 'ತಾಪ ಸ್ಥಿರವಾಗಿರಲಿ: ವಾಹಕತೆ ಪ್ರತಿ °C ಗೆ ಸುಮಾರು 2% ಏರುತ್ತದೆ.'), W('Do not touch the platinised electrodes.', 'प्लैटिनीकृत इलेक्ट्रोडों को न छुएँ।', 'ಪ್ಲಾಟಿನೀಕೃತ ವಿದ್ಯುದ್ವಾರಗಳನ್ನು ಮುಟ್ಟಬೇಡಿ.')],
        conclusion=W('HCl gives a V-shaped curve and acetic acid a gentle rise then a steep one; in both the lines meet at the equivalence point, which gives the acid’s strength without any indicator.', 'HCl से V-आकार का वक्र और ऐसीटिक अम्ल से पहले धीमा फिर तेज़ उठाव मिलता है; दोनों में रेखाएँ तुल्यता बिंदु पर मिलती हैं, जिससे बिना सूचक के अम्ल की प्रबलता मिलती है।', 'HCl V-ಆಕಾರದ ವಕ್ರ, ಅಸಿಟಿಕ್ ಆಮ್ಲ ಮೊದಲು ನಿಧಾನ ನಂತರ ಕಡಿದಾದ ಏರಿಕೆ ನೀಡುತ್ತವೆ; ಎರಡರಲ್ಲೂ ರೇಖೆಗಳು ಸಮತುಲ್ಯ ಬಿಂದುವಿನಲ್ಲಿ ಸೇರುತ್ತವೆ; ಸೂಚಕವಿಲ್ಲದೆ ಆಮ್ಲದ ಪ್ರಬಲತೆ ಸಿಗುತ್ತದೆ.'),
        viva=[Q(W('Why does H⁺ conduct so well?', 'H⁺ इतना अच्छा चालक क्यों है?', 'H⁺ ಏಕೆ ಇಷ್ಟು ಉತ್ತಮ ವಾಹಕ?'), W('Protons hop from one water molecule to the next (Grotthuss mechanism).', 'प्रोटॉन एक जल अणु से अगले पर कूदते हैं (ग्रॉटस क्रियाविधि)।', 'ಪ್ರೋಟಾನ್‌ಗಳು ಒಂದು ನೀರಿನ ಅಣುವಿನಿಂದ ಮುಂದಿನದಕ್ಕೆ ಜಿಗಿಯುತ್ತವೆ (ಗ್ರೋಟಸ್ ಕಾರ್ಯವಿಧಾನ).')),
              Q(W('Give one advantage of conductometric titration.', 'चालकतामितीय अनुमापन का एक लाभ बताइए।', 'ವಾಹಕತಾಮಾಪಕ ಅನುಮಾಪನದ ಒಂದು ಲಾಭ ತಿಳಿಸಿ.'), W('It works for coloured or very dilute solutions, where indicators fail.', 'यह रंगीन या बहुत तनु विलयनों के लिए काम करता है, जहाँ सूचक विफल रहते हैं।', 'ಸೂಚಕಗಳು ವಿಫಲವಾಗುವ ಬಣ್ಣದ ಅಥವಾ ಅತಿ ವಿರಳ ದ್ರಾವಣಗಳಿಗೆ ಇದು ಕೆಲಸ ಮಾಡುತ್ತದೆ.')),
              Q(W('What is the unit of conductance?', 'चालकता का मात्रक क्या है?', 'ವಾಹಕತೆಯ ಏಕಮಾನ ಯಾವುದು?'), W('Siemens (S), the reciprocal of ohm.', 'सीमेंस (S), ओम का व्युत्क्रम।', 'ಸೀಮೆನ್ಸ್ (S), ಓಮ್‌ನ ವಿಲೋಮ.'))])

    lab(id='reaction-rate-thiosulphate', bench='reaction-rate', levels=[12], curricula=['cbse', 'ncert', 'ka-puc'], **chem,
        keywords=['chemical kinetics', 'rate of reaction', 'sodium thiosulphate', 'sodium thiosulfate', 'concentration', 'temperature'],
        title=W('Rate of reaction: sodium thiosulphate and acid', 'अभिक्रिया की दर: सोडियम थायोसल्फ़ेट और अम्ल', 'ಪ್ರತಿಕ್ರಿಯೆಯ ದರ: ಸೋಡಿಯಂ ಥಯೋಸಲ್ಫೇಟ್ ಮತ್ತು ಆಮ್ಲ'),
        summary=W('Time how long the sulphur takes to hide a cross, at different concentrations and temperatures.', 'अलग-अलग सांद्रता और ताप पर गंधक को एक क्रॉस छिपाने में लगने वाला समय मापें।', 'ಬೇರೆ ಬೇರೆ ಸಾಂದ್ರತೆ ಮತ್ತು ತಾಪಗಳಲ್ಲಿ ಗಂಧಕ ಒಂದು ಅಡ್ಡಗುರುತು ಮುಚ್ಚಲು ತೆಗೆದುಕೊಳ್ಳುವ ಸಮಯ ಅಳೆಯಿರಿ.'),
        aim=W('To study the effect of concentration and temperature on the rate of reaction between sodium thiosulphate and hydrochloric acid.', 'सोडियम थायोसल्फ़ेट और हाइड्रोक्लोरिक अम्ल की अभिक्रिया की दर पर सांद्रता और ताप के प्रभाव का अध्ययन करना।', 'ಸೋಡಿಯಂ ಥಯೋಸಲ್ಫೇಟ್ ಮತ್ತು ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲದ ಪ್ರತಿಕ್ರಿಯಾ ದರದ ಮೇಲೆ ಸಾಂದ್ರತೆ ಮತ್ತು ತಾಪದ ಪರಿಣಾಮ ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
        principle=W('Na₂S₂O₃ + 2HCl → 2NaCl + SO₂ + S + H₂O. Colloidal sulphur clouds the solution; the time t for a fixed amount of sulphur to hide the cross is inversely proportional to the rate, so 1/t is a measure of the rate. 1/t ∝ [S₂O₃²⁻], and the rate roughly doubles for every 10 °C rise.', 'Na₂S₂O₃ + 2HCl → 2NaCl + SO₂ + S + H₂O. कोलॉइडी गंधक विलयन को धुँधला कर देता है; निश्चित मात्रा में गंधक को क्रॉस छिपाने में लगा समय t दर के व्युत्क्रमानुपाती है, इसलिए 1/t दर का माप है। 1/t ∝ [S₂O₃²⁻], और हर 10 °C वृद्धि पर दर लगभग दोगुनी होती है।', 'Na₂S₂O₃ + 2HCl → 2NaCl + SO₂ + S + H₂O. ಕಲಿಲ ಗಂಧಕ ದ್ರಾವಣವನ್ನು ಮಬ್ಬಾಗಿಸುತ್ತದೆ; ನಿಗದಿತ ಪ್ರಮಾಣದ ಗಂಧಕ ಅಡ್ಡಗುರುತು ಮುಚ್ಚಲು ಬೇಕಾದ ಸಮಯ t ದರಕ್ಕೆ ವಿಲೋಮಾನುಪಾತೀಯ; ಆದ್ದರಿಂದ 1/t ದರದ ಅಳತೆ. 1/t ∝ [S₂O₃²⁻], ಪ್ರತಿ 10 °C ಏರಿಕೆಗೆ ದರ ಸುಮಾರು ಎರಡು ಪಟ್ಟು.'),
        apparatus=[W('0.1 M sodium thiosulphate and 1 M HCl', '0.1 M सोडियम थायोसल्फ़ेट और 1 M HCl', '0.1 M ಸೋಡಿಯಂ ಥಯೋಸಲ್ಫೇಟ್ ಮತ್ತು 1 M HCl'), W('Conical flasks and measuring cylinders', 'शंक्वाकार फ्लास्क और मापक सिलिंडर', 'ಶಂಕುವಿನಾಕಾರದ ಫ್ಲಾಸ್ಕ್‌ಗಳು ಮತ್ತು ಅಳತೆ ಸಿಲಿಂಡರ್‌ಗಳು'), W('Paper marked with a cross', 'क्रॉस बने कागज़', 'ಅಡ್ಡಗುರುತು ಹಾಕಿದ ಕಾಗದ'), W('Stopwatch and water bath', 'विराम घड़ी और जल ऊष्मक', 'ನಿಲುಗಡಿಯಾರ ಮತ್ತು ನೀರಿನ ತೊಟ್ಟಿ')],
        steps=[W('Put 50 mL of thiosulphate in the flask on the cross.', 'क्रॉस पर रखे फ्लास्क में 50 mL थायोसल्फ़ेट डालें।', 'ಅಡ್ಡಗುರುತಿನ ಮೇಲಿನ ಫ್ಲಾಸ್ಕ್‌ಗೆ 50 mL ಥಯೋಸಲ್ಫೇಟ್ ಹಾಕಿ.'),
               W('Add 5 mL of HCl, start the stopwatch and swirl.', '5 mL HCl डालें, विराम घड़ी चालू करें और घुमाएँ।', '5 mL HCl ಸೇರಿಸಿ, ನಿಲುಗಡಿಯಾರ ಆರಂಭಿಸಿ ತಿರುಗಿಸಿ.'),
               W('Looking from above, stop the watch when the cross can no longer be seen.', 'ऊपर से देखते हुए, क्रॉस न दिखने पर घड़ी रोकें।', 'ಮೇಲಿನಿಂದ ನೋಡುತ್ತಾ ಅಡ್ಡಗುರುತು ಕಾಣದಾದಾಗ ಗಡಿಯಾರ ನಿಲ್ಲಿಸಿ.'),
               W('Repeat with 40, 30, 20 and 10 mL thiosulphate made up to 50 mL with water.', '40, 30, 20 और 10 mL थायोसल्फ़ेट को पानी से 50 mL बनाकर दोहराएँ।', '40, 30, 20 ಮತ್ತು 10 mL ಥಯೋಸಲ್ಫೇಟನ್ನು ನೀರಿನಿಂದ 50 mL ಮಾಡಿ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Repeat the 50 mL run at higher temperatures; plot 1/t against concentration.', '50 mL वाला प्रयोग अधिक ताप पर दोहराएँ; 1/t और सांद्रता का ग्राफ़ बनाएँ।', '50 mL ಪ್ರಯೋಗವನ್ನು ಹೆಚ್ಚು ತಾಪದಲ್ಲಿ ಪುನರಾವರ್ತಿಸಿ; 1/t ಮತ್ತು ಸಾಂದ್ರತೆ ನಕ್ಷೆ ಎಳೆಯಿರಿ.')],
        precautions=[W('Keep the total volume the same in every run.', 'हर प्रयोग में कुल आयतन समान रखें।', 'ಪ್ರತಿ ಪ್ರಯೋಗದಲ್ಲೂ ಒಟ್ಟು ಘನಫಲ ಒಂದೇ ಇರಲಿ.'), W('Work in a ventilated room: sulphur dioxide is given off.', 'हवादार कमरे में काम करें: सल्फ़र डाइऑक्साइड निकलती है।', 'ಗಾಳಿಯಾಡುವ ಕೋಣೆಯಲ್ಲಿ ಕೆಲಸ ಮಾಡಿ: ಸಲ್ಫರ್ ಡೈಆಕ್ಸೈಡ್ ಬಿಡುಗಡೆಯಾಗುತ್ತದೆ.'), W('Use the same cross and the same observer.', 'एक ही क्रॉस और एक ही प्रेक्षक रखें।', 'ಒಂದೇ ಅಡ್ಡಗುರುತು ಮತ್ತು ಒಂದೇ ವೀಕ್ಷಕ ಇರಲಿ.')],
        conclusion=W('The rate (1/t) is directly proportional to the thiosulphate concentration, and it about doubles for a 10 °C rise in temperature.', 'दर (1/t) थायोसल्फ़ेट की सांद्रता के अनुक्रमानुपाती है, और ताप में 10 °C वृद्धि पर लगभग दोगुनी होती है।', 'ದರ (1/t) ಥಯೋಸಲ್ಫೇಟ್ ಸಾಂದ್ರತೆಗೆ ನೇರ ಅನುಪಾತೀಯ; ತಾಪದಲ್ಲಿ 10 °C ಏರಿಕೆಗೆ ಸುಮಾರು ಎರಡು ಪಟ್ಟಾಗುತ್ತದೆ.'),
        viva=[Q(W('Why does temperature increase the rate so much?', 'ताप दर को इतना क्यों बढ़ाता है?', 'ತಾಪ ದರವನ್ನು ಇಷ್ಟು ಏಕೆ ಹೆಚ್ಚಿಸುತ್ತದೆ?'), W('Many more molecules have at least the activation energy (Arrhenius).', 'कहीं अधिक अणुओं के पास कम से कम सक्रियण ऊर्जा होती है (आर्हीनियस)।', 'ಹೆಚ್ಚು ಅಣುಗಳಿಗೆ ಕನಿಷ್ಠ ಸಕ್ರಿಯಗೊಳಿಸುವ ಶಕ್ತಿ ಇರುತ್ತದೆ (ಆರ್ಹೇನಿಯಸ್).')),
              Q(W('What is the order with respect to thiosulphate?', 'थायोसल्फ़ेट के सापेक्ष कोटि क्या है?', 'ಥಯೋಸಲ್ಫೇಟ್‌ಗೆ ಸಂಬಂಧಿಸಿ ಕ್ರಮಾಂಕ ಏನು?'), W('First order: 1/t is proportional to its concentration.', 'प्रथम कोटि: 1/t उसकी सांद्रता के अनुक्रमानुपाती है।', 'ಪ್ರಥಮ ಕ್ರಮಾಂಕ: 1/t ಅದರ ಸಾಂದ್ರತೆಗೆ ಅನುಪಾತೀಯ.')),
              Q(W('What makes the solution cloudy?', 'विलयन को धुँधला क्या बनाता है?', 'ದ್ರಾವಣವನ್ನು ಮಬ್ಬಾಗಿಸುವುದು ಯಾವುದು?'), W('Fine particles of sulphur (a colloid).', 'गंधक के बारीक कण (कोलॉइड)।', 'ಗಂಧಕದ ಸೂಕ್ಷ್ಮ ಕಣಗಳು (ಕಲಿಲ).'))])

    CHROM_APP = [W('Chromatography paper strips', 'क्रोमैटोग्राफ़ी कागज़ की पट्टियाँ', 'ವರ್ಣರೇಖನ ಕಾಗದದ ಪಟ್ಟಿಗಳು'), W('Glass jar with lid', 'ढक्कन सहित काँच का जार', 'ಮುಚ್ಚಳ ಸಹಿತ ಗಾಜಿನ ಜಾಡಿ'), W('Capillary tube for spotting', 'धब्बा लगाने के लिए केशिका नली', 'ಚುಕ್ಕೆ ಇಡಲು ಲೋಮನಾಳ'), W('Pencil and scale', 'पेंसिल और पैमाना', 'ಪೆನ್ಸಿಲ್ ಮತ್ತು ಅಳತೆಪಟ್ಟಿ')]
    CHROM_PRE = [W('Draw the starting line in pencil, not ink.', 'आरंभिक रेखा पेंसिल से खींचें, स्याही से नहीं।', 'ಆರಂಭಿಕ ರೇಖೆಯನ್ನು ಶಾಯಿಯಿಂದಲ್ಲ, ಪೆನ್ಸಿಲ್‌ನಿಂದ ಎಳೆಯಿರಿ.'), W('Keep the spot above the solvent level.', 'धब्बे को विलायक स्तर से ऊपर रखें।', 'ಚುಕ್ಕೆಯನ್ನು ದ್ರಾವಕ ಮಟ್ಟಕ್ಕಿಂತ ಮೇಲಿಡಿ.'), W('Keep the jar covered so the solvent vapour saturates it.', 'जार ढका रखें ताकि विलायक वाष्प उसे संतृप्त कर दे।', 'ದ್ರಾವಕ ಆವಿ ತುಂಬುವಂತೆ ಜಾಡಿಯನ್ನು ಮುಚ್ಚಿಡಿ.')]
    lab(id='leaf-pigment-chromatography', bench='chromatography', setup={'mixture': 'leaf'}, levels=[11, 12], curricula=['cbse', 'ncert', 'ka-puc'], subject='Chemistry', domain='chemistry',
        keywords=['chromatography', 'paper chromatography', 'leaf pigments', 'chlorophyll', 'rf value', 'photosynthesis', 'purification'],
        title=W('Separating leaf pigments by paper chromatography', 'कागज़ वर्णलेखन से पत्ती के वर्णक अलग करना', 'ಕಾಗದ ವರ್ಣರೇಖನದಿಂದ ಎಲೆಯ ವರ್ಣದ್ರವ್ಯಗಳನ್ನು ಬೇರ್ಪಡಿಸುವುದು'),
        summary=W('Run a spot of spinach extract up a paper strip and measure the Rf of each pigment.', 'पालक के सत्त के धब्बे को कागज़ की पट्टी पर चढ़ाएँ और हर वर्णक का Rf मापें।', 'ಪಾಲಕ್ ಸಾರದ ಚುಕ್ಕೆಯನ್ನು ಕಾಗದದ ಪಟ್ಟಿಯ ಮೇಲೆ ಏರಿಸಿ ಪ್ರತಿ ವರ್ಣದ್ರವ್ಯದ Rf ಅಳೆಯಿರಿ.'),
        aim=W('To separate the pigments of a green leaf by paper chromatography and find their Rf values.', 'कागज़ वर्णलेखन द्वारा हरी पत्ती के वर्णकों को अलग करना और उनके Rf मान ज्ञात करना।', 'ಕಾಗದ ವರ್ಣರೇಖನದಿಂದ ಹಸಿರು ಎಲೆಯ ವರ್ಣದ್ರವ್ಯಗಳನ್ನು ಬೇರ್ಪಡಿಸಿ ಅವುಗಳ Rf ಮೌಲ್ಯಗಳನ್ನು ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('The solvent rises through the paper by capillary action. Each pigment is shared between the moving solvent and the stationary water in the paper; the more it prefers the solvent, the further it travels. Rf = distance moved by the spot ÷ distance moved by the solvent front, a constant for a given pigment, paper and solvent.', 'विलायक केशिका क्रिया से कागज़ में ऊपर चढ़ता है। हर वर्णक चलते विलायक और कागज़ के स्थिर जल के बीच बँटता है; जितना वह विलायक को पसंद करता है, उतना आगे जाता है। Rf = धब्बे द्वारा तय दूरी ÷ विलायक अग्र द्वारा तय दूरी, जो किसी वर्णक, कागज़ और विलायक के लिए नियत है।', 'ದ್ರಾವಕ ಲೋಮನಾಳ ಕ್ರಿಯೆಯಿಂದ ಕಾಗದದಲ್ಲಿ ಏರುತ್ತದೆ. ಪ್ರತಿ ವರ್ಣದ್ರವ್ಯ ಚಲಿಸುವ ದ್ರಾವಕ ಮತ್ತು ಕಾಗದದ ಸ್ಥಿರ ನೀರಿನ ನಡುವೆ ಹಂಚಿಕೊಳ್ಳುತ್ತದೆ; ದ್ರಾವಕವನ್ನು ಎಷ್ಟು ಇಷ್ಟಪಡುತ್ತದೋ ಅಷ್ಟು ದೂರ ಹೋಗುತ್ತದೆ. Rf = ಚುಕ್ಕೆ ಕ್ರಮಿಸಿದ ದೂರ ÷ ದ್ರಾವಕ ಮುಂಚೂಣಿ ಕ್ರಮಿಸಿದ ದೂರ; ಒಂದು ವರ್ಣದ್ರವ್ಯ, ಕಾಗದ ಮತ್ತು ದ್ರಾವಕಕ್ಕೆ ಸ್ಥಿರ.'),
        apparatus=CHROM_APP + [W('Spinach leaves, acetone, and petroleum ether–acetone (9 : 1)', 'पालक की पत्तियाँ, ऐसीटोन, और पेट्रोलियम ईथर–ऐसीटोन (9 : 1)', 'ಪಾಲಕ್ ಎಲೆಗಳು, ಅಸಿಟೋನ್, ಮತ್ತು ಪೆಟ್ರೋಲಿಯಂ ಈಥರ್–ಅಸಿಟೋನ್ (9 : 1)')],
        steps=[W('Grind the leaves with a little acetone to get a dark green extract.', 'पत्तियों को थोड़े ऐसीटोन के साथ पीसकर गहरा हरा सत्त बनाएँ।', 'ಎಲೆಗಳನ್ನು ಸ್ವಲ್ಪ ಅಸಿಟೋನ್ ಜೊತೆ ಅರೆದು ಗಾಢ ಹಸಿರು ಸಾರ ಪಡೆಯಿರಿ.'),
               W('Put a small concentrated spot of extract on the pencil line, drying between applications.', 'पेंसिल रेखा पर सत्त का छोटा, गाढ़ा धब्बा लगाएँ, हर बार बीच में सुखाएँ।', 'ಪೆನ್ಸಿಲ್ ರೇಖೆಯ ಮೇಲೆ ಸಾರದ ಸಣ್ಣ ಸಾಂದ್ರ ಚುಕ್ಕೆ ಇಡಿ, ಪ್ರತಿ ಬಾರಿ ಒಣಗಿಸಿ.'),
               W('Hang the strip in the jar with its end in the solvent and close the lid.', 'पट्टी को जार में ऐसे लटकाएँ कि उसका सिरा विलायक में हो, और ढक्कन बंद करें।', 'ಪಟ್ಟಿಯನ್ನು ಅದರ ತುದಿ ದ್ರಾವಕದಲ್ಲಿರುವಂತೆ ಜಾಡಿಯಲ್ಲಿ ತೂಗುಹಾಕಿ ಮುಚ್ಚಳ ಮುಚ್ಚಿ.'),
               W('When the front is near the top, take the strip out and mark the front.', 'अग्र ऊपर के पास पहुँचने पर पट्टी निकालें और अग्र पर निशान लगाएँ।', 'ಮುಂಚೂಣಿ ಮೇಲ್ಭಾಗದ ಹತ್ತಿರ ಬಂದಾಗ ಪಟ್ಟಿ ತೆಗೆದು ಮುಂಚೂಣಿ ಗುರುತಿಸಿ.'),
               W('Measure the distance of each coloured band and work out its Rf.', 'हर रंगीन पट्टी की दूरी मापकर उसका Rf निकालें।', 'ಪ್ರತಿ ಬಣ್ಣದ ಪಟ್ಟೆಯ ದೂರ ಅಳೆದು ಅದರ Rf ಲೆಕ್ಕಿಸಿ.')],
        precautions=CHROM_PRE,
        conclusion=W('Leaf extract separates into carotene, xanthophyll, chlorophyll a and chlorophyll b, each with its own Rf: green leaves contain several pigments.', 'पत्ती का सत्त कैरोटीन, ज़ैंथोफ़िल, क्लोरोफ़िल a और क्लोरोफ़िल b में अलग होता है, हर एक का अपना Rf: हरी पत्तियों में कई वर्णक होते हैं।', 'ಎಲೆಯ ಸಾರ ಕ್ಯಾರೋಟಿನ್, ಕ್ಸಾಂಥೋಫಿಲ್, ಕ್ಲೋರೋಫಿಲ್ a ಮತ್ತು ಕ್ಲೋರೋಫಿಲ್ b ಆಗಿ ಬೇರ್ಪಡುತ್ತದೆ, ಪ್ರತಿಯೊಂದಕ್ಕೂ ತನ್ನದೇ Rf: ಹಸಿರು ಎಲೆಗಳಲ್ಲಿ ಹಲವು ವರ್ಣದ್ರವ್ಯಗಳಿವೆ.'),
        viva=[Q(W('Can an Rf value be greater than 1?', 'क्या Rf मान 1 से अधिक हो सकता है?', 'Rf ಮೌಲ್ಯ 1 ಕ್ಕಿಂತ ಹೆಚ್ಚಿರಬಹುದೇ?'), W('No: no spot can move further than the solvent.', 'नहीं: कोई धब्बा विलायक से आगे नहीं जा सकता।', 'ಇಲ್ಲ: ಯಾವ ಚುಕ್ಕೆಯೂ ದ್ರಾವಕಕ್ಕಿಂತ ಮುಂದೆ ಹೋಗಲಾರದು.')),
              Q(W('Which pigment travels furthest, and why?', 'कौन-सा वर्णक सबसे दूर जाता है, और क्यों?', 'ಯಾವ ವರ್ಣದ್ರವ್ಯ ಅತಿ ದೂರ ಹೋಗುತ್ತದೆ, ಏಕೆ?'), W('Carotene: it is the least polar, so it stays with the non-polar solvent.', 'कैरोटीन: यह सबसे कम ध्रुवीय है, इसलिए अध्रुवीय विलायक के साथ रहता है।', 'ಕ್ಯಾರೋಟಿನ್: ಅದು ಅತಿ ಕಡಿಮೆ ಧ್ರುವೀಯ, ಆದ್ದರಿಂದ ಅಧ್ರುವೀಯ ದ್ರಾವಕದೊಂದಿಗೆ ಇರುತ್ತದೆ.')),
              Q(W('What is the stationary phase in paper chromatography?', 'कागज़ वर्णलेखन में स्थिर प्रावस्था क्या है?', 'ಕಾಗದ ವರ್ಣರೇಖನದಲ್ಲಿ ಸ್ಥಿರ ಪ್ರಾವಸ್ಥೆ ಯಾವುದು?'), W('Water held in the cellulose fibres of the paper.', 'कागज़ के सेलुलोज़ रेशों में रुका जल।', 'ಕಾಗದದ ಸೆಲ್ಯುಲೋಸ್ ನಾರುಗಳಲ್ಲಿ ಹಿಡಿದಿರುವ ನೀರು.'))])

    lab(id='ink-chromatography', bench='chromatography', setup={'mixture': 'inks'}, subject='Forensics', domain='forensics', levels=[9, 10, 11, 12, 'ug'], curricula=['forensics'],
        keywords=['forensic', 'ink analysis', 'questioned document', 'chromatography', 'forgery', 'rf value'],
        title=W('Forensic ink analysis by chromatography', 'वर्णलेखन द्वारा न्यायालयिक स्याही विश्लेषण', 'ವರ್ಣರೇಖನದಿಂದ ವಿಧಿವಿಜ್ಞಾನ ಶಾಯಿ ವಿಶ್ಲೇಷಣೆ'),
        summary=W('Separate the ink of a ransom note and of three suspects’ pens, and see which pen matches.', 'फिरौती के पत्र की और तीन संदिग्धों के पेनों की स्याही अलग करें, और देखें कि कौन-सा पेन मेल खाता है।', 'ಸುಲಿಗೆ ಪತ್ರದ ಮತ್ತು ಮೂವರು ಶಂಕಿತರ ಪೆನ್ನುಗಳ ಶಾಯಿಯನ್ನು ಬೇರ್ಪಡಿಸಿ, ಯಾವ ಪೆನ್ ಹೊಂದುತ್ತದೆ ನೋಡಿ.'),
        aim=W('To compare the ink on a questioned document with inks from suspects’ pens using paper chromatography.', 'कागज़ वर्णलेखन से संदिग्ध दस्तावेज़ की स्याही की तुलना संदिग्धों के पेनों की स्याही से करना।', 'ಕಾಗದ ವರ್ಣರೇಖನದಿಂದ ಪ್ರಶ್ನಿತ ದಾಖಲೆಯ ಶಾಯಿಯನ್ನು ಶಂಕಿತರ ಪೆನ್ನುಗಳ ಶಾಯಿಯೊಂದಿಗೆ ಹೋಲಿಸುವುದು.'),
        principle=W('Most inks are mixtures of dyes. Chromatography separates them into spots with characteristic Rf values. If the note’s ink gives the same dyes at the same Rf values as a pen’s ink, that pen (or one with the same ink) could have been used; a different pattern rules the pen out.', 'अधिकांश स्याहियाँ रंजकों का मिश्रण होती हैं। वर्णलेखन उन्हें विशिष्ट Rf मानों वाले धब्बों में अलग करता है। यदि पत्र की स्याही किसी पेन की स्याही जैसे ही रंजक समान Rf पर देती है, तो वह पेन (या उसी स्याही वाला) प्रयुक्त हो सकता है; भिन्न प्रतिरूप उस पेन को बाहर कर देता है।', 'ಹೆಚ್ಚಿನ ಶಾಯಿಗಳು ಬಣ್ಣಗಳ ಮಿಶ್ರಣ. ವರ್ಣರೇಖನ ಅವುಗಳನ್ನು ವಿಶಿಷ್ಟ Rf ಮೌಲ್ಯಗಳ ಚುಕ್ಕೆಗಳಾಗಿ ಬೇರ್ಪಡಿಸುತ್ತದೆ. ಪತ್ರದ ಶಾಯಿ ಒಂದು ಪೆನ್ನಿನ ಶಾಯಿಯಂತೆಯೇ ಅದೇ Rf ನಲ್ಲಿ ಅದೇ ಬಣ್ಣಗಳನ್ನು ನೀಡಿದರೆ ಆ ಪೆನ್ (ಅಥವಾ ಅದೇ ಶಾಯಿಯದು) ಬಳಸಿರಬಹುದು; ಬೇರೆ ಮಾದರಿ ಆ ಪೆನ್ನನ್ನು ಹೊರಗಿಡುತ್ತದೆ.'),
        apparatus=CHROM_APP + [W('Ink sample cut from the note; pens A, B and C', 'पत्र से काटा स्याही नमूना; पेन A, B और C', 'ಪತ್ರದಿಂದ ಕತ್ತರಿಸಿದ ಶಾಯಿ ಮಾದರಿ; ಪೆನ್ನುಗಳು A, B ಮತ್ತು C'), W('Solvent: water–ethanol (or butanol–ethanol–ammonia)', 'विलायक: जल–एथेनॉल (या ब्यूटेनॉल–एथेनॉल–अमोनिया)', 'ದ್ರಾವಕ: ನೀರು–ಎಥೆನಾಲ್ (ಅಥವಾ ಬ್ಯೂಟನಾಲ್–ಎಥೆನಾಲ್–ಅಮೋನಿಯಾ)')],
        steps=[W('Spot the note’s ink and each pen’s ink on separate strips (or side by side on one sheet).', 'पत्र की स्याही और हर पेन की स्याही अलग पट्टियों पर (या एक ही शीट पर साथ-साथ) लगाएँ।', 'ಪತ್ರದ ಶಾಯಿ ಮತ್ತು ಪ್ರತಿ ಪೆನ್ನಿನ ಶಾಯಿಯನ್ನು ಬೇರೆ ಪಟ್ಟಿಗಳ ಮೇಲೆ (ಅಥವಾ ಒಂದೇ ಹಾಳೆಯಲ್ಲಿ ಪಕ್ಕಪಕ್ಕ) ಇಡಿ.'),
               W('Develop all the strips together in the same solvent.', 'सभी पट्टियों को एक ही विलायक में साथ विकसित करें।', 'ಎಲ್ಲ ಪಟ್ಟಿಗಳನ್ನು ಒಂದೇ ದ್ರಾವಕದಲ್ಲಿ ಒಟ್ಟಿಗೆ ಅಭಿವೃದ್ಧಿಪಡಿಸಿ.'),
               W('Mark the solvent front and measure every spot.', 'विलायक अग्र पर निशान लगाकर हर धब्बा मापें।', 'ದ್ರಾವಕ ಮುಂಚೂಣಿ ಗುರುತಿಸಿ ಪ್ರತಿ ಚುಕ್ಕೆ ಅಳೆಯಿರಿ.'),
               W('Compare the colours and Rf values of the note with each pen.', 'पत्र के रंगों और Rf मानों की हर पेन से तुलना करें।', 'ಪತ್ರದ ಬಣ್ಣಗಳು ಮತ್ತು Rf ಮೌಲ್ಯಗಳನ್ನು ಪ್ರತಿ ಪೆನ್ನಿನೊಂದಿಗೆ ಹೋಲಿಸಿ.'),
               W('Record which pens are excluded and which cannot be excluded.', 'लिखें कि कौन-से पेन बाहर हुए और कौन-से बाहर नहीं किए जा सकते।', 'ಯಾವ ಪೆನ್ನುಗಳು ಹೊರಗುಳಿದವು, ಯಾವುವು ಹೊರಗಿಡಲಾಗದು ಬರೆಯಿರಿ.')],
        precautions=CHROM_PRE + [W('Handle evidence with gloves and label every sample.', 'साक्ष्य को दस्ताने पहनकर संभालें और हर नमूने पर लेबल लगाएँ।', 'ಸಾಕ್ಷ್ಯವನ್ನು ಕೈಗವಸು ಧರಿಸಿ ನಿರ್ವಹಿಸಿ, ಪ್ರತಿ ಮಾದರಿಗೆ ಹಣೆಪಟ್ಟಿ ಹಾಕಿ.')],
        conclusion=W('Only one pen’s ink gives the same dyes at the same Rf values as the note; the others are excluded. A match is supporting evidence, since many pens can share one ink.', 'केवल एक पेन की स्याही पत्र जैसे ही रंजक समान Rf पर देती है; बाकी बाहर हो जाते हैं। मेल केवल सहायक साक्ष्य है, क्योंकि कई पेनों में एक ही स्याही हो सकती है।', 'ಒಂದೇ ಪೆನ್ನಿನ ಶಾಯಿ ಮಾತ್ರ ಪತ್ರದಂತೆಯೇ ಅದೇ Rf ನಲ್ಲಿ ಅದೇ ಬಣ್ಣಗಳನ್ನು ನೀಡುತ್ತದೆ; ಉಳಿದವು ಹೊರಗುಳಿಯುತ್ತವೆ. ಹೊಂದಿಕೆ ಪೂರಕ ಸಾಕ್ಷ್ಯ ಮಾತ್ರ, ಏಕೆಂದರೆ ಹಲವು ಪೆನ್ನುಗಳಲ್ಲಿ ಒಂದೇ ಶಾಯಿ ಇರಬಹುದು.'),
        viva=[Q(W('Why is a match not proof that the suspect wrote the note?', 'मेल यह प्रमाण क्यों नहीं कि संदिग्ध ने पत्र लिखा?', 'ಹೊಂದಿಕೆ ಶಂಕಿತನೇ ಪತ್ರ ಬರೆದನೆಂಬುದಕ್ಕೆ ಪುರಾವೆ ಏಕೆ ಅಲ್ಲ?'), W('Many pens of the same brand share the same ink; it only shows the pen could have been used.', 'एक ही ब्रांड के कई पेनों में एक ही स्याही होती है; यह केवल दिखाता है कि वह पेन प्रयुक्त हो सकता था।', 'ಒಂದೇ ಬ್ರ್ಯಾಂಡ್‌ನ ಹಲವು ಪೆನ್ನುಗಳಲ್ಲಿ ಒಂದೇ ಶಾಯಿ; ಆ ಪೆನ್ ಬಳಸಿರಬಹುದು ಎಂದು ಮಾತ್ರ ತೋರಿಸುತ್ತದೆ.')),
              Q(W('Why are all samples run on the same sheet?', 'सभी नमूने एक ही शीट पर क्यों चलाए जाते हैं?', 'ಎಲ್ಲ ಮಾದರಿಗಳನ್ನು ಒಂದೇ ಹಾಳೆಯಲ್ಲಿ ಏಕೆ ಓಡಿಸುತ್ತಾರೆ?'), W('So the paper, solvent and conditions are identical and Rf values can be compared directly.', 'ताकि कागज़, विलायक और परिस्थितियाँ एक-सी हों और Rf मान सीधे तुलनीय हों।', 'ಕಾಗದ, ದ್ರಾವಕ ಮತ್ತು ಪರಿಸ್ಥಿತಿಗಳು ಒಂದೇ ಆಗಿದ್ದು Rf ಮೌಲ್ಯಗಳನ್ನು ನೇರವಾಗಿ ಹೋಲಿಸಲು.')),
              Q(W('Name a more sensitive method used in forensic labs.', 'न्यायालयिक प्रयोगशालाओं में प्रयुक्त अधिक संवेदनशील विधि बताइए।', 'ವಿಧಿವಿಜ್ಞಾನ ಪ್ರಯೋಗಾಲಯಗಳಲ್ಲಿ ಬಳಸುವ ಹೆಚ್ಚು ಸಂವೇದಿ ವಿಧಾನ ಹೆಸರಿಸಿ.'), W('Thin-layer chromatography (TLC) or HPLC.', 'पतली परत वर्णलेखन (TLC) या HPLC.', 'ತೆಳು ಪದರ ವರ್ಣರೇಖನ (TLC) ಅಥವಾ HPLC.'))])

    lab(id='enthalpy-neutralisation', bench='neutralisation', levels=[11, 12], curricula=['cbse', 'ncert', 'ka-puc'], **chem,
        keywords=['thermochemistry', 'enthalpy of neutralisation', 'enthalpy of neutralization', 'calorimetry', 'thermodynamics', 'heat of reaction'],
        title=W('Enthalpy of neutralisation', 'उदासीनीकरण की एन्थैल्पी', 'ತಟಸ್ಥೀಕರಣದ ಎಂಥಾಲ್ಪಿ'),
        summary=W('Mix acid and alkali in an insulated cup, read the temperature rise and work out ΔH.', 'ऊष्मारोधी कप में अम्ल और क्षार मिलाएँ, ताप वृद्धि पढ़ें और ΔH निकालें।', 'ಉಷ್ಣನಿರೋಧಕ ಕಪ್‌ನಲ್ಲಿ ಆಮ್ಲ ಮತ್ತು ಕ್ಷಾರ ಬೆರೆಸಿ, ತಾಪ ಏರಿಕೆ ಓದಿ ΔH ಲೆಕ್ಕಿಸಿ.'),
        aim=W('To find the enthalpy of neutralisation of a strong acid (HCl) and a weak acid (acetic acid) with sodium hydroxide.', 'सोडियम हाइड्रॉक्साइड से प्रबल अम्ल (HCl) और दुर्बल अम्ल (ऐसीटिक अम्ल) के उदासीनीकरण की एन्थैल्पी ज्ञात करना।', 'ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್‌ನೊಂದಿಗೆ ಪ್ರಬಲ ಆಮ್ಲ (HCl) ಮತ್ತು ದುರ್ಬಲ ಆಮ್ಲ (ಅಸಿಟಿಕ್ ಆಮ್ಲ) ದ ತಟಸ್ಥೀಕರಣ ಎಂಥಾಲ್ಪಿ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Neutralisation is H⁺ + OH⁻ → H₂O, ΔH ≈ −57 kJ per mole of water for any strong acid and strong base. The heat raises the temperature of the solution and the calorimeter: q = (mc + W)ΔT, and ΔH = −q ÷ moles of water. A weak acid gives a little less, because some heat is used to ionise it.', 'उदासीनीकरण H⁺ + OH⁻ → H₂O है, किसी भी प्रबल अम्ल-प्रबल क्षार के लिए प्रति मोल जल ΔH ≈ −57 kJ. ऊष्मा विलयन और कैलोरीमीटर का ताप बढ़ाती है: q = (mc + W)ΔT, और ΔH = −q ÷ जल के मोल। दुर्बल अम्ल थोड़ा कम देता है, क्योंकि कुछ ऊष्मा उसे आयनित करने में लगती है।', 'ತಟಸ್ಥೀಕರಣ H⁺ + OH⁻ → H₂O, ಯಾವುದೇ ಪ್ರಬಲ ಆಮ್ಲ-ಪ್ರಬಲ ಕ್ಷಾರಕ್ಕೆ ಪ್ರತಿ ಮೋಲ್ ನೀರಿಗೆ ΔH ≈ −57 kJ. ಉಷ್ಣ ದ್ರಾವಣ ಮತ್ತು ಕ್ಯಾಲೊರಿಮೀಟರ್‌ನ ತಾಪ ಏರಿಸುತ್ತದೆ: q = (mc + W)ΔT, ΔH = −q ÷ ನೀರಿನ ಮೋಲ್. ದುರ್ಬಲ ಆಮ್ಲ ಸ್ವಲ್ಪ ಕಡಿಮೆ ನೀಡುತ್ತದೆ, ಏಕೆಂದರೆ ಸ್ವಲ್ಪ ಉಷ್ಣ ಅದನ್ನು ಅಯಾನೀಕರಿಸಲು ಬಳಕೆಯಾಗುತ್ತದೆ.'),
        apparatus=[W('Polystyrene cup calorimeter with lid', 'ढक्कन सहित पॉलीस्टाइरीन कप कैलोरीमीटर', 'ಮುಚ್ಚಳ ಸಹಿತ ಪಾಲಿಸ್ಟೈರೀನ್ ಕಪ್ ಕ್ಯಾಲೊರಿಮೀಟರ್'), W('Thermometer (0.1 °C)', 'तापमापी (0.1 °C)', 'ತಾಪಮಾಪಕ (0.1 °C)'), W('1 M HCl, 1 M acetic acid and 1 M NaOH', '1 M HCl, 1 M ऐसीटिक अम्ल और 1 M NaOH', '1 M HCl, 1 M ಅಸಿಟಿಕ್ ಆಮ್ಲ ಮತ್ತು 1 M NaOH'), W('Measuring cylinders (50 mL)', 'मापक सिलिंडर (50 mL)', 'ಅಳತೆ ಸಿಲಿಂಡರ್‌ಗಳು (50 mL)')],
        steps=[W('Find the water equivalent of the calorimeter (or use the value given).', 'कैलोरीमीटर का जल तुल्यांक ज्ञात करें (या दिया गया मान लें)।', 'ಕ್ಯಾಲೊರಿಮೀಟರ್‌ನ ಜಲ ಸಮಾನಾಂಕ ಕಂಡುಹಿಡಿಯಿರಿ (ಅಥವಾ ಕೊಟ್ಟ ಮೌಲ್ಯ ಬಳಸಿ).'),
               W('Put 50 mL of 1 M HCl in the cup and note its temperature; check the NaOH is at the same temperature.', 'कप में 50 mL 1 M HCl डालकर उसका ताप लिखें; जाँचें कि NaOH उसी ताप पर है।', 'ಕಪ್‌ನಲ್ಲಿ 50 mL 1 M HCl ಹಾಕಿ ಅದರ ತಾಪ ಬರೆಯಿರಿ; NaOH ಅದೇ ತಾಪದಲ್ಲಿದೆಯೇ ಪರಿಶೀಲಿಸಿ.'),
               W('Pour in 50 mL of 1 M NaOH, stir and record the highest temperature.', '50 mL 1 M NaOH डालें, हिलाएँ और सबसे अधिक ताप लिखें।', '50 mL 1 M NaOH ಸುರಿದು ಕಲಕಿ ಅತಿ ಹೆಚ್ಚಿನ ತಾಪ ದಾಖಲಿಸಿ.'),
               W('Work out q and ΔH per mole of water formed.', 'q और बने जल के प्रति मोल ΔH निकालें।', 'q ಮತ್ತು ಉಂಟಾದ ನೀರಿನ ಪ್ರತಿ ಮೋಲ್‌ಗೆ ΔH ಲೆಕ್ಕಿಸಿ.'),
               W('Repeat with acetic acid and compare.', 'ऐसीटिक अम्ल के साथ दोहराएँ और तुलना करें।', 'ಅಸಿಟಿಕ್ ಆಮ್ಲದೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ ಹೋಲಿಸಿ.')],
        precautions=[W('Keep the cup covered and stir gently to lose little heat.', 'ऊष्मा हानि कम रखने के लिए कप ढका रखें और धीरे हिलाएँ।', 'ಉಷ್ಣ ನಷ್ಟ ಕಡಿಮೆ ಇರಲು ಕಪ್ ಮುಚ್ಚಿ ನಿಧಾನವಾಗಿ ಕಲಕಿ.'), W('Start with both solutions at the same temperature.', 'दोनों विलयन एक ही ताप से शुरू करें।', 'ಎರಡೂ ದ್ರಾವಣಗಳನ್ನು ಒಂದೇ ತಾಪದಿಂದ ಆರಂಭಿಸಿ.'), GOGGLES],
        conclusion=W('The strong acid gives about −57 kJ per mole of water; acetic acid a little less, as part of the heat goes to ionising the weak acid.', 'प्रबल अम्ल प्रति मोल जल लगभग −57 kJ देता है; ऐसीटिक अम्ल थोड़ा कम, क्योंकि ऊष्मा का कुछ भाग दुर्बल अम्ल को आयनित करने में जाता है।', 'ಪ್ರಬಲ ಆಮ್ಲ ಪ್ರತಿ ಮೋಲ್ ನೀರಿಗೆ ಸುಮಾರು −57 kJ ನೀಡುತ್ತದೆ; ಅಸಿಟಿಕ್ ಆಮ್ಲ ಸ್ವಲ್ಪ ಕಡಿಮೆ, ಏಕೆಂದರೆ ಉಷ್ಣದ ಭಾಗ ದುರ್ಬಲ ಆಮ್ಲವನ್ನು ಅಯಾನೀಕರಿಸಲು ಹೋಗುತ್ತದೆ.'),
        viva=[Q(W('Why is ΔH the same for every strong acid and strong base?', 'हर प्रबल अम्ल-प्रबल क्षार के लिए ΔH समान क्यों है?', 'ಪ್ರತಿ ಪ್ರಬಲ ಆಮ್ಲ-ಪ್ರಬಲ ಕ್ಷಾರಕ್ಕೆ ΔH ಏಕೆ ಒಂದೇ?'), W('Both are fully ionised, so the only reaction is H⁺ + OH⁻ → H₂O.', 'दोनों पूर्णतः आयनित हैं, इसलिए एकमात्र अभिक्रिया H⁺ + OH⁻ → H₂O है।', 'ಎರಡೂ ಸಂಪೂರ್ಣ ಅಯಾನೀಕೃತ; ಆದ್ದರಿಂದ ಇರುವ ಪ್ರತಿಕ್ರಿಯೆ H⁺ + OH⁻ → H₂O ಮಾತ್ರ.')),
              Q(W('Is neutralisation exothermic or endothermic?', 'उदासीनीकरण ऊष्माक्षेपी है या ऊष्माशोषी?', 'ತಟಸ್ಥೀಕರಣ ಉಷ್ಣವಿಮೋಚಕವೇ ಉಷ್ಣಶೋಷಕವೇ?'), W('Exothermic: ΔH is negative.', 'ऊष्माक्षेपी: ΔH ऋणात्मक है।', 'ಉಷ್ಣವಿಮೋಚಕ: ΔH ಋಣ.')),
              Q(W('Why use a polystyrene cup?', 'पॉलीस्टाइरीन कप क्यों?', 'ಪಾಲಿಸ್ಟೈರೀನ್ ಕಪ್ ಏಕೆ?'), W('It is a poor conductor with a small heat capacity, so little heat is lost.', 'यह कम ऊष्मा धारिता वाला कुचालक है, इसलिए कम ऊष्मा खोती है।', 'ಅದು ಕಡಿಮೆ ಉಷ್ಣ ಧಾರಣಶಕ್ತಿಯ ಅವಾಹಕ; ಆದ್ದರಿಂದ ಕಡಿಮೆ ಉಷ್ಣ ನಷ್ಟ.'))])

    lab(id='ester-hydrolysis', bench='ester-hydrolysis', **ug,
        keywords=['chemical kinetics', 'ester hydrolysis', 'methyl acetate', 'first order reaction', 'rate constant', 'acid catalysis'],
        title=W('Kinetics of acid hydrolysis of methyl acetate', 'मेथिल ऐसीटेट के अम्लीय जल-अपघटन की गतिकी', 'ಮೀಥೈಲ್ ಅಸಿಟೇಟ್‌ನ ಆಮ್ಲ ಜಲವಿಭಜನೆಯ ಚಲನಶಾಸ್ತ್ರ'),
        summary=W('Titrate samples of the reaction mixture over time; the log plot gives the first-order rate constant.', 'समय के साथ अभिक्रिया मिश्रण के नमूनों का अनुमापन करें; लघुगणक ग्राफ़ से प्रथम कोटि दर नियतांक मिलता है।', 'ಸಮಯದೊಂದಿಗೆ ಪ್ರತಿಕ್ರಿಯಾ ಮಿಶ್ರಣದ ಮಾದರಿಗಳನ್ನು ಅನುಮಾಪನ ಮಾಡಿ; ಲಾಗ್ ನಕ್ಷೆ ಪ್ರಥಮ ಕ್ರಮಾಂಕ ದರ ಸ್ಥಿರಾಂಕ ನೀಡುತ್ತದೆ.'),
        aim=W('To find the rate constant of the acid-catalysed hydrolysis of methyl acetate at two temperatures.', 'दो तापों पर मेथिल ऐसीटेट के अम्ल-उत्प्रेरित जल-अपघटन का दर नियतांक ज्ञात करना।', 'ಎರಡು ತಾಪಗಳಲ್ಲಿ ಮೀಥೈಲ್ ಅಸಿಟೇಟ್‌ನ ಆಮ್ಲ-ವೇಗವರ್ಧಿತ ಜಲವಿಭಜನೆಯ ದರ ಸ್ಥಿರಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('CH₃COOCH₃ + H₂O → CH₃COOH + CH₃OH, catalysed by H⁺. Water is in large excess, so the reaction is pseudo-first order. The acetic acid formed raises the titre against NaOH: k = (2.303/t) log((V∞ − V₀)/(V∞ − Vt)), so log(V∞ − Vt) against t is a straight line of slope −k/2.303.', 'CH₃COOCH₃ + H₂O → CH₃COOH + CH₃OH, H⁺ द्वारा उत्प्रेरित। जल बहुत अधिक मात्रा में है, इसलिए अभिक्रिया छद्म-प्रथम कोटि की है। बना ऐसीटिक अम्ल NaOH से अनुमापांक बढ़ाता है: k = (2.303/t) log((V∞ − V₀)/(V∞ − Vt)), अतः log(V∞ − Vt) और t का ग्राफ़ −k/2.303 प्रवणता की सीधी रेखा है।', 'CH₃COOCH₃ + H₂O → CH₃COOH + CH₃OH, H⁺ ವೇಗವರ್ಧಿತ. ನೀರು ಅತಿ ಹೆಚ್ಚು ಪ್ರಮಾಣದಲ್ಲಿರುವುದರಿಂದ ಪ್ರತಿಕ್ರಿಯೆ ಹುಸಿ-ಪ್ರಥಮ ಕ್ರಮಾಂಕ. ಉಂಟಾದ ಅಸಿಟಿಕ್ ಆಮ್ಲ NaOH ವಿರುದ್ಧ ಅನುಮಾಪನಾಂಕ ಏರಿಸುತ್ತದೆ: k = (2.303/t) log((V∞ − V₀)/(V∞ − Vt)); ಆದ್ದರಿಂದ log(V∞ − Vt) ಮತ್ತು t ನಕ್ಷೆ −k/2.303 ಇಳಿಜಾರಿನ ಸರಳರೇಖೆ.'),
        apparatus=[W('Methyl acetate and 0.5 M HCl', 'मेथिल ऐसीटेट और 0.5 M HCl', 'ಮೀಥೈಲ್ ಅಸಿಟೇಟ್ ಮತ್ತು 0.5 M HCl'), W('0.2 M NaOH and phenolphthalein', '0.2 M NaOH और फ़िनॉल्फ़्थेलिन', '0.2 M NaOH ಮತ್ತು ಫೀನಾಲ್ಫ್ತಲೀನ್'), BURETTE, W('Thermostat bath, ice and stopwatch', 'थर्मोस्टैट ऊष्मक, बर्फ़ और विराम घड़ी', 'ಥರ್ಮೋಸ್ಟಾಟ್ ತೊಟ್ಟಿ, ಮಂಜುಗಡ್ಡೆ ಮತ್ತು ನಿಲುಗಡಿಯಾರ')],
        steps=[W('Mix 5 mL of ester with 100 mL of HCl in the bath and start the clock.', 'ऊष्मक में 5 mL एस्टर को 100 mL HCl के साथ मिलाकर घड़ी चालू करें।', 'ತೊಟ್ಟಿಯಲ್ಲಿ 5 mL ಎಸ್ಟರನ್ನು 100 mL HCl ಜೊತೆ ಬೆರೆಸಿ ಗಡಿಯಾರ ಆರಂಭಿಸಿ.'),
               W('At once, and every 10–20 minutes, pipette 5 mL into ice water and titrate with NaOH (Vt).', 'तुरंत और हर 10–20 मिनट पर 5 mL बर्फ़ीले पानी में पिपेट से लें और NaOH से अनुमापन करें (Vt)।', 'ತಕ್ಷಣ ಮತ್ತು ಪ್ರತಿ 10–20 ನಿಮಿಷಕ್ಕೆ 5 mL ಅನ್ನು ಮಂಜುಗಡ್ಡೆ ನೀರಿಗೆ ಪಿಪೆಟ್ ಮಾಡಿ NaOH ನಿಂದ ಅನುಮಾಪನ ಮಾಡಿ (Vt).'),
               W('Heat a sample to complete the reaction and titrate it for V∞.', 'एक नमूने को गरम कर अभिक्रिया पूरी करें और V∞ के लिए अनुमापन करें।', 'ಒಂದು ಮಾದರಿಯನ್ನು ಬಿಸಿಮಾಡಿ ಪ್ರತಿಕ್ರಿಯೆ ಪೂರ್ಣಗೊಳಿಸಿ V∞ ಗಾಗಿ ಅನುಮಾಪನ ಮಾಡಿ.'),
               W('Plot log(V∞ − Vt) against t; k = −2.303 × slope.', 'log(V∞ − Vt) और t का ग्राफ़ बनाएँ; k = −2.303 × प्रवणता।', 'log(V∞ − Vt) ಮತ್ತು t ನಕ್ಷೆ ಎಳೆಯಿರಿ; k = −2.303 × ಇಳಿಜಾರು.'),
               W('Repeat at 35 °C and estimate the activation energy from the two k values.', '35 °C पर दोहराएँ और दो k मानों से सक्रियण ऊर्जा का अनुमान लगाएँ।', '35 °C ನಲ್ಲಿ ಪುನರಾವರ್ತಿಸಿ ಎರಡು k ಮೌಲ್ಯಗಳಿಂದ ಸಕ್ರಿಯಗೊಳಿಸುವ ಶಕ್ತಿ ಅಂದಾಜಿಸಿ.'), CSV],
        precautions=[W('Quench each sample in ice water to stop the reaction before titrating.', 'अनुमापन से पहले हर नमूने को बर्फ़ीले पानी में डालकर अभिक्रिया रोकें।', 'ಅನುಮಾಪನದ ಮೊದಲು ಪ್ರತಿ ಮಾದರಿಯನ್ನು ಮಂಜುಗಡ್ಡೆ ನೀರಿನಲ್ಲಿ ಹಾಕಿ ಪ್ರತಿಕ್ರಿಯೆ ನಿಲ್ಲಿಸಿ.'), W('Keep the bath temperature constant.', 'ऊष्मक का ताप नियत रखें।', 'ತೊಟ್ಟಿಯ ತಾಪ ಸ್ಥಿರವಾಗಿರಲಿ.'), W('Note the exact time each sample is taken.', 'हर नमूना लेने का सटीक समय लिखें।', 'ಪ್ರತಿ ಮಾದರಿ ತೆಗೆದ ನಿಖರ ಸಮಯ ಬರೆಯಿರಿ.')],
        conclusion=W('log(V∞ − Vt) falls linearly with time, so the hydrolysis is (pseudo) first order; k is a few × 10⁻³ per minute at 25 °C and larger at 35 °C.', 'log(V∞ − Vt) समय के साथ रैखिक रूप से घटता है, इसलिए जल-अपघटन (छद्म) प्रथम कोटि का है; 25 °C पर k कुछ × 10⁻³ प्रति मिनट और 35 °C पर अधिक है।', 'log(V∞ − Vt) ಸಮಯದೊಂದಿಗೆ ರೇಖೀಯವಾಗಿ ಇಳಿಯುತ್ತದೆ; ಆದ್ದರಿಂದ ಜಲವಿಭಜನೆ (ಹುಸಿ) ಪ್ರಥಮ ಕ್ರಮಾಂಕ; 25 °C ನಲ್ಲಿ k ಕೆಲವು × 10⁻³ ಪ್ರತಿ ನಿಮಿಷ, 35 °C ನಲ್ಲಿ ಹೆಚ್ಚು.'),
        viva=[Q(W('Why is it called pseudo-first order?', 'इसे छद्म-प्रथम कोटि क्यों कहते हैं?', 'ಇದನ್ನು ಹುಸಿ-ಪ್ರಥಮ ಕ್ರಮಾಂಕ ಏಕೆ ಎನ್ನುತ್ತಾರೆ?'), W('Water takes part but is in such excess that its concentration hardly changes.', 'जल भाग लेता है पर इतना अधिक है कि उसकी सांद्रता लगभग नहीं बदलती।', 'ನೀರು ಭಾಗವಹಿಸುತ್ತದೆ, ಆದರೆ ಅಷ್ಟು ಹೆಚ್ಚಿರುವುದರಿಂದ ಅದರ ಸಾಂದ್ರತೆ ಬಹುತೇಕ ಬದಲಾಗುವುದಿಲ್ಲ.')),
              Q(W('What does V₀ measure?', 'V₀ क्या मापता है?', 'V₀ ಏನನ್ನು ಅಳೆಯುತ್ತದೆ?'), W('The HCl catalyst only, before any acetic acid has formed.', 'केवल HCl उत्प्रेरक, कोई ऐसीटिक अम्ल बनने से पहले।', 'ಯಾವುದೇ ಅಸಿಟಿಕ್ ಆಮ್ಲ ಉಂಟಾಗುವ ಮೊದಲು HCl ವೇಗವರ್ಧಕ ಮಾತ್ರ.')),
              Q(W('How is the half-life related to k?', 'अर्ध-आयु का k से क्या संबंध है?', 'ಅರ್ಧಾಯುಷ್ಯ k ಯೊಂದಿಗೆ ಹೇಗೆ ಸಂಬಂಧಿಸಿದೆ?'), W('t½ = 0.693 ÷ k, independent of concentration.', 't½ = 0.693 ÷ k, सांद्रता से स्वतंत्र।', 't½ = 0.693 ÷ k, ಸಾಂದ್ರತೆಯಿಂದ ಸ್ವತಂತ್ರ.'))])

    lab(id='beer-lambert', bench='beer-lambert', **ug,
        keywords=['colorimetry', 'spectrophotometry', 'beer-lambert law', 'beer lambert', 'absorbance', 'potassium permanganate', 'calibration curve'],
        title=W('Beer–Lambert law with a colorimeter', 'वर्णमापी से बीयर–लैम्बर्ट नियम', 'ವರ್ಣಮಾಪಕದಿಂದ ಬಿಯರ್–ಲ್ಯಾಂಬರ್ಟ್ ನಿಯಮ'),
        summary=W('Find λmax for KMnO₄, make a calibration line from standards and read an unknown concentration.', 'KMnO₄ के लिए λmax ज्ञात करें, मानकों से अंशांकन रेखा बनाएँ और अज्ञात सांद्रता पढ़ें।', 'KMnO₄ ಗೆ λmax ಕಂಡುಹಿಡಿದು, ಮಾನಕಗಳಿಂದ ಮಾಪನಾಂಕ ರೇಖೆ ರಚಿಸಿ ಅಜ್ಞಾತ ಸಾಂದ್ರತೆ ಓದಿ.'),
        aim=W('To verify the Beer–Lambert law for potassium permanganate and find the concentration of an unknown solution.', 'पोटैशियम परमैंगनेट के लिए बीयर–लैम्बर्ट नियम का सत्यापन करना और अज्ञात विलयन की सांद्रता ज्ञात करना।', 'ಪೊಟ್ಯಾಸಿಯಂ ಪರ್ಮ್ಯಾಂಗನೇಟ್‌ಗೆ ಬಿಯರ್–ಲ್ಯಾಂಬರ್ಟ್ ನಿಯಮ ಪರಿಶೀಲಿಸಿ ಅಜ್ಞಾತ ದ್ರಾವಣದ ಸಾಂದ್ರತೆ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Absorbance A = log(I₀/I) = εlc: at a fixed wavelength and path length, A is proportional to concentration. Measuring at the wavelength of maximum absorbance (λmax ≈ 525 nm for KMnO₄) gives the steepest, most sensitive line.', 'अवशोषणांक A = log(I₀/I) = εlc: नियत तरंगदैर्घ्य और पथ लंबाई पर A सांद्रता के अनुक्रमानुपाती है। अधिकतम अवशोषण की तरंगदैर्घ्य (KMnO₄ के लिए λmax ≈ 525 nm) पर मापने से सबसे खड़ी, सबसे संवेदनशील रेखा मिलती है।', 'ಹೀರಿಕೆ A = log(I₀/I) = εlc: ನಿಗದಿತ ತರಂಗಾಂತರ ಮತ್ತು ಪಥ ಉದ್ದದಲ್ಲಿ A ಸಾಂದ್ರತೆಗೆ ಅನುಪಾತೀಯ. ಗರಿಷ್ಠ ಹೀರಿಕೆಯ ತರಂಗಾಂತರದಲ್ಲಿ (KMnO₄ ಗೆ λmax ≈ 525 nm) ಅಳೆದರೆ ಅತಿ ಕಡಿದಾದ, ಅತಿ ಸಂವೇದಿ ರೇಖೆ ಸಿಗುತ್ತದೆ.'),
        apparatus=[W('Colorimeter (or spectrophotometer) with 1 cm cuvettes', '1 cm क्यूवेट सहित वर्णमापी (या स्पेक्ट्रोफ़ोटोमीटर)', '1 cm ಕ್ಯುವೆಟ್‌ಗಳ ಸಹಿತ ವರ್ಣಮಾಪಕ (ಅಥವಾ ಸ್ಪೆಕ್ಟ್ರೋಫೋಟೋಮೀಟರ್)'), W('KMnO₄ standards (1–5 × 10⁻⁴ M) and an unknown', 'KMnO₄ मानक (1–5 × 10⁻⁴ M) और एक अज्ञात', 'KMnO₄ ಮಾನಕಗಳು (1–5 × 10⁻⁴ M) ಮತ್ತು ಒಂದು ಅಜ್ಞಾತ'), W('Distilled water as the blank', 'रिक्त के रूप में आसुत जल', 'ಖಾಲಿಯಾಗಿ ಬಟ್ಟಿ ನೀರು'), W('Volumetric flasks and pipettes', 'आयतनमितीय फ्लास्क और पिपेट', 'ಘನಫಲಮಾಪಕ ಫ್ಲಾಸ್ಕ್‌ಗಳು ಮತ್ತು ಪಿಪೆಟ್‌ಗಳು')],
        steps=[W('Set zero absorbance with the blank.', 'रिक्त से अवशोषणांक शून्य करें।', 'ಖಾಲಿಯಿಂದ ಹೀರಿಕೆಯನ್ನು ಶೂನ್ಯಗೊಳಿಸಿ.'),
               W('With one standard, read A from 400 to 700 nm and find λmax.', 'एक मानक के साथ 400 से 700 nm तक A पढ़ें और λmax ज्ञात करें।', 'ಒಂದು ಮಾನಕದೊಂದಿಗೆ 400 ರಿಂದ 700 nm ವರೆಗೆ A ಓದಿ λmax ಕಂಡುಹಿಡಿಯಿರಿ.'),
               W('At λmax, read every standard and plot A against c.', 'λmax पर हर मानक पढ़ें और A तथा c का ग्राफ़ बनाएँ।', 'λmax ನಲ್ಲಿ ಪ್ರತಿ ಮಾನಕ ಓದಿ A ಮತ್ತು c ನಕ್ಷೆ ಎಳೆಯಿರಿ.'),
               W('Read the unknown and find its concentration from the line.', 'अज्ञात को पढ़ें और रेखा से उसकी सांद्रता ज्ञात करें।', 'ಅಜ್ಞಾತವನ್ನು ಓದಿ ರೇಖೆಯಿಂದ ಅದರ ಸಾಂದ್ರತೆ ಕಂಡುಹಿಡಿಯಿರಿ.'), CSV],
        precautions=[W('Hold cuvettes by their frosted sides and wipe the clear faces.', 'क्यूवेट को उनकी खुरदरी सतहों से पकड़ें और पारदर्शी सतहें पोंछें।', 'ಕ್ಯುವೆಟ್‌ಗಳನ್ನು ಮಬ್ಬು ಬದಿಗಳಿಂದ ಹಿಡಿದು ಪಾರದರ್ಶಕ ಮುಖಗಳನ್ನು ಒರೆಸಿ.'), W('Rinse the cuvette with each solution before filling.', 'भरने से पहले क्यूवेट को हर विलयन से धोएँ।', 'ತುಂಬುವ ಮೊದಲು ಕ್ಯುವೆಟನ್ನು ಪ್ರತಿ ದ್ರಾವಣದಿಂದ ತೊಳೆಯಿರಿ.'), W('Keep absorbances below about 1 where the law holds best.', 'अवशोषणांक लगभग 1 से कम रखें जहाँ नियम सबसे अच्छा लागू होता है।', 'ನಿಯಮ ಉತ್ತಮವಾಗಿ ಅನ್ವಯಿಸುವ ಸುಮಾರು 1 ಕ್ಕಿಂತ ಕಡಿಮೆ ಹೀರಿಕೆಯಲ್ಲಿರಲಿ.')],
        conclusion=W('Absorbance is proportional to concentration at λmax (Beer–Lambert law); the calibration line gives ε and the unknown concentration.', 'λmax पर अवशोषणांक सांद्रता के अनुक्रमानुपाती है (बीयर–लैम्बर्ट नियम); अंशांकन रेखा ε और अज्ञात सांद्रता देती है।', 'λmax ನಲ್ಲಿ ಹೀರಿಕೆ ಸಾಂದ್ರತೆಗೆ ಅನುಪಾತೀಯ (ಬಿಯರ್–ಲ್ಯಾಂಬರ್ಟ್ ನಿಯಮ); ಮಾಪನಾಂಕ ರೇಖೆ ε ಮತ್ತು ಅಜ್ಞಾತ ಸಾಂದ್ರತೆ ನೀಡುತ್ತದೆ.'),
        viva=[Q(W('Why does KMnO₄ look purple if it absorbs at 525 nm?', 'KMnO₄ 525 nm पर अवशोषित करता है तो बैंगनी क्यों दिखता है?', 'KMnO₄ 525 nm ನಲ್ಲಿ ಹೀರಿದರೆ ನೇರಳೆಯಾಗಿ ಏಕೆ ಕಾಣುತ್ತದೆ?'), W('It absorbs green light; we see the complementary colours, red and blue: purple.', 'यह हरा प्रकाश अवशोषित करता है; हम पूरक रंग, लाल और नीला, देखते हैं: बैंगनी।', 'ಅದು ಹಸಿರು ಬೆಳಕನ್ನು ಹೀರುತ್ತದೆ; ನಾವು ಪೂರಕ ಬಣ್ಣಗಳಾದ ಕೆಂಪು ಮತ್ತು ನೀಲಿ ನೋಡುತ್ತೇವೆ: ನೇರಳೆ.')),
              Q(W('What is the unit of ε?', 'ε का मात्रक क्या है?', 'ε ದ ಏಕಮಾನ ಯಾವುದು?'), W('L mol⁻¹ cm⁻¹.', 'L mol⁻¹ cm⁻¹ (लीटर प्रति मोल प्रति सेंटीमीटर)।', 'L mol⁻¹ cm⁻¹ (ಪ್ರತಿ ಮೋಲ್ ಪ್ರತಿ ಸೆಂಟಿಮೀಟರ್‌ಗೆ ಲೀಟರ್).')),
              Q(W('Why is a blank used?', 'रिक्त क्यों प्रयोग होता है?', 'ಖಾಲಿಯನ್ನು ಏಕೆ ಬಳಸುತ್ತಾರೆ?'), W('To cancel absorption by the solvent and the cuvette.', 'विलायक और क्यूवेट द्वारा अवशोषण को निरस्त करने के लिए।', 'ದ್ರಾವಕ ಮತ್ತು ಕ್ಯುವೆಟ್‌ನ ಹೀರಿಕೆಯನ್ನು ರದ್ದುಗೊಳಿಸಲು.'))])

    lab(id='ostwald-viscosity', bench='ostwald', **ug,
        keywords=['viscosity', 'ostwald viscometer', 'relative viscosity', 'liquids', 'physical chemistry'],
        title=W('Viscosity of liquids with an Ostwald viscometer', 'ऑस्टवाल्ड श्यानतामापी से द्रवों की श्यानता', 'ಆಸ್ಟ್‌ವಾಲ್ಡ್ ಸ್ನಿಗ್ಧತಾಮಾಪಕದಿಂದ ದ್ರವಗಳ ಸ್ನಿಗ್ಧತೆ'),
        summary=W('Time each liquid between the two marks and compare with water to find its viscosity.', 'हर द्रव का दो निशानों के बीच समय लें और पानी से तुलना करके उसकी श्यानता ज्ञात करें।', 'ಪ್ರತಿ ದ್ರವದ ಎರಡು ಗುರುತುಗಳ ನಡುವಿನ ಸಮಯ ಅಳೆದು ನೀರಿನೊಂದಿಗೆ ಹೋಲಿಸಿ ಅದರ ಸ್ನಿಗ್ಧತೆ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To find the viscosity of given liquids relative to water using an Ostwald viscometer.', 'ऑस्टवाल्ड श्यानतामापी से पानी के सापेक्ष दिए गए द्रवों की श्यानता ज्ञात करना।', 'ಆಸ್ಟ್‌ವಾಲ್ಡ್ ಸ್ನಿಗ್ಧತಾಮಾಪಕದಿಂದ ನೀರಿಗೆ ಸಾಪೇಕ್ಷವಾಗಿ ಕೊಟ್ಟ ದ್ರವಗಳ ಸ್ನಿಗ್ಧತೆ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('By Poiseuille’s law the time for a fixed volume to flow through the capillary under its own weight is proportional to η/ρ. So η₁/η₂ = ρ₁t₁ / ρ₂t₂, and with water as the reference η = η_water × ρt ÷ (ρ_w t_w).', 'प्वाज़ॉय नियम से निश्चित आयतन के अपने भार से केशिका में बहने का समय η/ρ के अनुक्रमानुपाती है। अतः η₁/η₂ = ρ₁t₁ / ρ₂t₂, और पानी को संदर्भ लेकर η = η_water × ρt ÷ (ρ_w t_w).', 'ಪಾಯ್ಸೆಲ್ ನಿಯಮದಂತೆ ನಿಗದಿತ ಘನಫಲ ತನ್ನ ತೂಕದಿಂದ ಲೋಮನಾಳದಲ್ಲಿ ಹರಿಯುವ ಸಮಯ η/ρ ಗೆ ಅನುಪಾತೀಯ. ಆದ್ದರಿಂದ η₁/η₂ = ρ₁t₁ / ρ₂t₂; ನೀರನ್ನು ಉಲ್ಲೇಖವಾಗಿಟ್ಟು η = η_water × ρt ÷ (ρ_w t_w).'),
        apparatus=[W('Ostwald viscometer', 'ऑस्टवाल्ड श्यानतामापी', 'ಆಸ್ಟ್‌ವಾಲ್ಡ್ ಸ್ನಿಗ್ಧತಾಮಾಪಕ'), W('Thermostat bath', 'थर्मोस्टैट ऊष्मक', 'ಥರ್ಮೋಸ್ಟಾಟ್ ತೊಟ್ಟಿ'), W('Stopwatch', 'विराम घड़ी', 'ನಿಲುಗಡಿಯಾರ'), W('Specific gravity bottle (for densities)', 'विशिष्ट गुरुत्व बोतल (घनत्व के लिए)', 'ವಿಶಿಷ್ಟ ಗುರುತ್ವ ಬಾಟಲಿ (ಸಾಂದ್ರತೆಗಾಗಿ)')],
        steps=[W('Clean and dry the viscometer and clamp it vertically in the bath.', 'श्यानतामापी साफ़ और सूखा करके ऊष्मक में ऊर्ध्वाधर क्लैंप करें।', 'ಸ್ನಿಗ್ಧತಾಮಾಪಕವನ್ನು ಸ್ವಚ್ಛ, ಒಣಗಿಸಿ ತೊಟ್ಟಿಯಲ್ಲಿ ಲಂಬವಾಗಿ ಕ್ಲ್ಯಾಂಪ್ ಮಾಡಿ.'),
               W('Fill a fixed volume of water, suck it above the upper mark, and time its fall from the upper to the lower mark.', 'पानी का नियत आयतन भरें, उसे ऊपरी निशान से ऊपर खींचें, और ऊपरी से निचले निशान तक गिरने का समय लें।', 'ನೀರಿನ ನಿಗದಿತ ಘನಫಲ ತುಂಬಿ, ಮೇಲಿನ ಗುರುತಿನ ಮೇಲಕ್ಕೆ ಎಳೆದು, ಮೇಲಿನಿಂದ ಕೆಳಗಿನ ಗುರುತಿನವರೆಗೆ ಇಳಿಯುವ ಸಮಯ ಅಳೆಯಿರಿ.'),
               W('Repeat three times and take the mean.', 'तीन बार दोहराकर माध्य लें।', 'ಮೂರು ಬಾರಿ ಪುನರಾವರ್ತಿಸಿ ಸರಾಸರಿ ತೆಗೆಯಿರಿ.'),
               W('Do the same with each liquid (the same volume), and find its density.', 'हर द्रव के साथ (समान आयतन) यही करें, और उसका घनत्व ज्ञात करें।', 'ಪ್ರತಿ ದ್ರವದೊಂದಿಗೆ (ಅದೇ ಘನಫಲ) ಹೀಗೆಯೇ ಮಾಡಿ ಅದರ ಸಾಂದ್ರತೆ ಕಂಡುಹಿಡಿಯಿರಿ.'),
               W('Work out each viscosity relative to water.', 'हर श्यानता पानी के सापेक्ष निकालें।', 'ಪ್ರತಿ ಸ್ನಿಗ್ಧತೆಯನ್ನು ನೀರಿಗೆ ಸಾಪೇಕ್ಷವಾಗಿ ಲೆಕ್ಕಿಸಿ.')],
        precautions=[W('Use exactly the same volume of every liquid.', 'हर द्रव का ठीक समान आयतन लें।', 'ಪ್ರತಿ ದ್ರವದ ನಿಖರವಾಗಿ ಅದೇ ಘನಫಲ ಬಳಸಿ.'), W('Keep the temperature constant: viscosity changes quickly with it.', 'ताप नियत रखें: श्यानता उसके साथ तेज़ी से बदलती है।', 'ತಾಪ ಸ್ಥಿರವಾಗಿರಲಿ: ಸ್ನಿಗ್ಧತೆ ಅದರೊಂದಿಗೆ ವೇಗವಾಗಿ ಬದಲಾಗುತ್ತದೆ.'), W('The viscometer must be clean: dust in the capillary changes the time.', 'श्यानतामापी साफ़ हो: केशिका में धूल समय बदल देती है।', 'ಸ್ನಿಗ್ಧತಾಮಾಪಕ ಸ್ವಚ್ಛವಾಗಿರಲಿ: ಲೋಮನಾಳದಲ್ಲಿನ ಧೂಳು ಸಮಯ ಬದಲಿಸುತ್ತದೆ.')],
        conclusion=W('Flow time depends on η/ρ; acetone is far less viscous than water, while ethanol and glycerol solutions are more viscous.', 'बहाव समय η/ρ पर निर्भर करता है; ऐसीटोन पानी से कहीं कम श्यान है, जबकि एथेनॉल और ग्लिसरॉल विलयन अधिक श्यान हैं।', 'ಹರಿವಿನ ಸಮಯ η/ρ ಅನ್ನು ಅವಲಂಬಿಸಿದೆ; ಅಸಿಟೋನ್ ನೀರಿಗಿಂತ ಬಹಳ ಕಡಿಮೆ ಸ್ನಿಗ್ಧ, ಎಥೆನಾಲ್ ಮತ್ತು ಗ್ಲಿಸರಾಲ್ ದ್ರಾವಣಗಳು ಹೆಚ್ಚು ಸ್ನಿಗ್ಧ.'),
        viva=[Q(W('What is viscosity?', 'श्यानता क्या है?', 'ಸ್ನಿಗ್ಧತೆ ಎಂದರೇನು?'), W('A liquid’s internal friction: its resistance to flow.', 'द्रव का आंतरिक घर्षण: बहाव का उसका प्रतिरोध।', 'ದ್ರವದ ಆಂತರಿಕ ಘರ್ಷಣೆ: ಹರಿವಿಗೆ ಅದರ ಪ್ರತಿರೋಧ.')),
              Q(W('How does the viscosity of a liquid change with temperature?', 'ताप के साथ द्रव की श्यानता कैसे बदलती है?', 'ತಾಪದೊಂದಿಗೆ ದ್ರವದ ಸ್ನಿಗ್ಧತೆ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ?'), W('It decreases as the temperature rises.', 'ताप बढ़ने पर यह घटती है।', 'ತಾಪ ಏರಿದಂತೆ ಅದು ಕಡಿಮೆಯಾಗುತ್ತದೆ.')),
              Q(W('Why is glycerol so viscous?', 'ग्लिसरॉल इतना श्यान क्यों है?', 'ಗ್ಲಿಸರಾಲ್ ಏಕೆ ಇಷ್ಟು ಸ್ನಿಗ್ಧ?'), W('Its three OH groups form many hydrogen bonds between molecules.', 'इसके तीन OH समूह अणुओं के बीच अनेक हाइड्रोजन बंध बनाते हैं।', 'ಅದರ ಮೂರು OH ಗುಂಪುಗಳು ಅಣುಗಳ ನಡುವೆ ಹಲವು ಹೈಡ್ರೋಜನ್ ಬಂಧಗಳನ್ನು ರೂಪಿಸುತ್ತವೆ.'))])

    lab(id='flame-test', bench='flame-test', levels=[11, 12], mode='explore', curricula=['cbse', 'ncert', 'ka-puc'], **chem,
        keywords=['flame test', 'metal ions', 'salt analysis', 'cations', 's-block elements', 'emission'],
        title=W('Flame tests for metal ions', 'धातु आयनों के लिए ज्वाला परीक्षण', 'ಲೋಹ ಅಯಾನುಗಳ ಜ್ವಾಲಾ ಪರೀಕ್ಷೆ'),
        summary=W('Hold salts in a Bunsen flame on a nichrome wire and match each colour to its metal ion.', 'नाइक्रोम तार पर लवणों को बुन्सन ज्वाला में रखें और हर रंग को उसके धातु आयन से मिलाएँ।', 'ನೈಕ್ರೋಮ್ ತಂತಿಯ ಮೇಲೆ ಲವಣಗಳನ್ನು ಬನ್ಸನ್ ಜ್ವಾಲೆಯಲ್ಲಿ ಹಿಡಿದು ಪ್ರತಿ ಬಣ್ಣವನ್ನು ಅದರ ಲೋಹ ಅಯಾನಿಗೆ ಹೊಂದಿಸಿ.'),
        aim=W('To identify metal ions from the colours they give to a flame.', 'धातु आयनों द्वारा ज्वाला को दिए गए रंगों से उन्हें पहचानना।', 'ಲೋಹ ಅಯಾನುಗಳು ಜ್ವಾಲೆಗೆ ನೀಡುವ ಬಣ್ಣಗಳಿಂದ ಅವುಗಳನ್ನು ಗುರುತಿಸುವುದು.'),
        principle=W('Heat excites electrons in the metal atoms to higher energy levels. As they fall back they give out light of particular wavelengths, so each metal colours the flame in its own way: sodium golden yellow, potassium lilac, calcium brick red, strontium crimson, barium apple green, copper blue-green.', 'ऊष्मा धातु परमाणुओं के इलेक्ट्रॉनों को उच्च ऊर्जा स्तरों पर उत्तेजित करती है। लौटते समय वे विशेष तरंगदैर्घ्य का प्रकाश देते हैं, इसलिए हर धातु ज्वाला को अपने ढंग से रंगती है: सोडियम सुनहरा पीला, पोटैशियम लाइलक, कैल्शियम ईंट जैसा लाल, स्ट्रॉन्शियम किरमिजी, बेरियम सेब जैसा हरा, ताँबा नीला-हरा।', 'ಉಷ್ಣ ಲೋಹ ಪರಮಾಣುಗಳ ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳನ್ನು ಹೆಚ್ಚಿನ ಶಕ್ತಿ ಮಟ್ಟಗಳಿಗೆ ಉದ್ರೇಕಿಸುತ್ತದೆ. ಹಿಂತಿರುಗುವಾಗ ಅವು ನಿರ್ದಿಷ್ಟ ತರಂಗಾಂತರದ ಬೆಳಕು ನೀಡುತ್ತವೆ; ಆದ್ದರಿಂದ ಪ್ರತಿ ಲೋಹ ಜ್ವಾಲೆಗೆ ತನ್ನದೇ ಬಣ್ಣ ನೀಡುತ್ತದೆ: ಸೋಡಿಯಂ ಚಿನ್ನದ ಹಳದಿ, ಪೊಟ್ಯಾಸಿಯಂ ತಿಳಿ ನೇರಳೆ, ಕ್ಯಾಲ್ಸಿಯಂ ಇಟ್ಟಿಗೆ ಕೆಂಪು, ಸ್ಟ್ರಾನ್ಷಿಯಂ ಕಡುಗೆಂಪು, ಬೇರಿಯಂ ಸೇಬು ಹಸಿರು, ತಾಮ್ರ ನೀಲಿ-ಹಸಿರು.'),
        apparatus=[W('Bunsen burner', 'बुन्सन बर्नर', 'ಬನ್ಸನ್ ಬರ್ನರ್'), W('Nichrome wire loop on a glass rod', 'काँच की छड़ पर नाइक्रोम तार का फंदा', 'ಗಾಜಿನ ಕಡ್ಡಿಯ ಮೇಲೆ ನೈಕ್ರೋಮ್ ತಂತಿಯ ಕುಣಿಕೆ'), W('Concentrated HCl in a watch glass', 'वॉच ग्लास में सांद्र HCl', 'ವಾಚ್ ಗ್ಲಾಸ್‌ನಲ್ಲಿ ಸಾಂದ್ರ HCl'), W('Chlorides of Na, K, Ca, Sr, Ba, Cu, Li; blue cobalt glass', 'Na, K, Ca, Sr, Ba, Cu, Li के क्लोराइड; नीला कोबाल्ट काँच', 'Na, K, Ca, Sr, Ba, Cu, Li ಕ್ಲೋರೈಡ್‌ಗಳು; ನೀಲಿ ಕೋಬಾಲ್ಟ್ ಗಾಜು')],
        steps=[W('Clean the wire by dipping it in HCl and heating until it gives no colour.', 'तार को HCl में डुबोकर तब तक गरम करें जब तक वह कोई रंग न दे।', 'ತಂತಿಯನ್ನು HCl ನಲ್ಲಿ ಅದ್ದಿ ಯಾವ ಬಣ್ಣವೂ ನೀಡದವರೆಗೆ ಬಿಸಿಮಾಡಿ ಸ್ವಚ್ಛಗೊಳಿಸಿ.'),
               W('Make a paste of the salt with HCl on the wire.', 'तार पर लवण का HCl के साथ लेप बनाएँ।', 'ತಂತಿಯ ಮೇಲೆ ಲವಣವನ್ನು HCl ಜೊತೆ ಪೇಸ್ಟ್ ಮಾಡಿ.'),
               W('Hold it in the edge of the non-luminous flame and note the colour.', 'इसे अदीप्त ज्वाला के किनारे पर रखें और रंग देखें।', 'ಅದನ್ನು ಪ್ರಕಾಶರಹಿತ ಜ್ವಾಲೆಯ ಅಂಚಿನಲ್ಲಿ ಹಿಡಿದು ಬಣ್ಣ ಗಮನಿಸಿ.'),
               W('Clean the wire and repeat for every salt; view potassium through cobalt glass.', 'तार साफ़ करें और हर लवण के लिए दोहराएँ; पोटैशियम को कोबाल्ट काँच से देखें।', 'ತಂತಿ ಸ್ವಚ್ಛಗೊಳಿಸಿ ಪ್ರತಿ ಲವಣಕ್ಕೆ ಪುನರಾವರ್ತಿಸಿ; ಪೊಟ್ಯಾಸಿಯಂ ಅನ್ನು ಕೋಬಾಲ್ಟ್ ಗಾಜಿನ ಮೂಲಕ ನೋಡಿ.')],
        precautions=[W('Clean the wire well between salts; traces of sodium hide other colours.', 'लवणों के बीच तार अच्छी तरह साफ़ करें; सोडियम के अंश दूसरे रंग छिपा देते हैं।', 'ಲವಣಗಳ ನಡುವೆ ತಂತಿಯನ್ನು ಚೆನ್ನಾಗಿ ಸ್ವಚ್ಛಗೊಳಿಸಿ; ಸೋಡಿಯಂ ಕುರುಹುಗಳು ಇತರ ಬಣ್ಣಗಳನ್ನು ಮರೆಮಾಡುತ್ತವೆ.'), W('Handle concentrated HCl with care, away from the face.', 'सांद्र HCl को सावधानी से, चेहरे से दूर संभालें।', 'ಸಾಂದ್ರ HCl ಅನ್ನು ಎಚ್ಚರಿಕೆಯಿಂದ, ಮುಖದಿಂದ ದೂರ ನಿರ್ವಹಿಸಿ.'), W('Barium salts are poisonous: wash hands afterwards.', 'बेरियम लवण विषैले हैं: बाद में हाथ धोएँ।', 'ಬೇರಿಯಂ ಲವಣಗಳು ವಿಷಕಾರಿ: ನಂತರ ಕೈ ತೊಳೆಯಿರಿ.')],
        conclusion=W('Each metal ion gives a characteristic flame colour, which helps identify the cation in salt analysis (and is the basis of fireworks and flame photometry).', 'हर धातु आयन विशिष्ट ज्वाला रंग देता है, जो लवण विश्लेषण में धनायन पहचानने में सहायक है (और आतिशबाज़ी तथा ज्वाला प्रकाशमिति का आधार है)।', 'ಪ್ರತಿ ಲೋಹ ಅಯಾನು ವಿಶಿಷ್ಟ ಜ್ವಾಲಾ ಬಣ್ಣ ನೀಡುತ್ತದೆ; ಇದು ಲವಣ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಧನಾಯನ ಗುರುತಿಸಲು ಸಹಾಯಕ (ಮತ್ತು ಪಟಾಕಿ ಹಾಗೂ ಜ್ವಾಲಾ ಫೋಟೋಮಿತಿಯ ಆಧಾರ).'),
        viva=[Q(W('Why is concentrated HCl used?', 'सांद्र HCl क्यों प्रयोग होता है?', 'ಸಾಂದ್ರ HCl ಏಕೆ ಬಳಸುತ್ತಾರೆ?'), W('Metal chlorides are volatile, so they reach the flame easily.', 'धातु क्लोराइड वाष्पशील होते हैं, इसलिए आसानी से ज्वाला तक पहुँचते हैं।', 'ಲೋಹ ಕ್ಲೋರೈಡ್‌ಗಳು ಬಾಷ್ಪಶೀಲ; ಆದ್ದರಿಂದ ಸುಲಭವಾಗಿ ಜ್ವಾಲೆ ತಲುಪುತ್ತವೆ.')),
              Q(W('Why look at potassium through cobalt glass?', 'पोटैशियम को कोबाल्ट काँच से क्यों देखते हैं?', 'ಪೊಟ್ಯಾಸಿಯಂ ಅನ್ನು ಕೋಬಾಲ್ಟ್ ಗಾಜಿನ ಮೂಲಕ ಏಕೆ ನೋಡುತ್ತಾರೆ?'), W('The blue glass absorbs the yellow of any sodium impurity.', 'नीला काँच किसी भी सोडियम अशुद्धि का पीला रंग सोख लेता है।', 'ನೀಲಿ ಗಾಜು ಯಾವುದೇ ಸೋಡಿಯಂ ಕಲ್ಮಶದ ಹಳದಿಯನ್ನು ಹೀರುತ್ತದೆ.')),
              Q(W('Why does Mg not colour the flame?', 'Mg ज्वाला को रंग क्यों नहीं देता?', 'Mg ಜ್ವಾಲೆಗೆ ಬಣ್ಣ ಏಕೆ ನೀಡುವುದಿಲ್ಲ?'), W('Its electrons are held too strongly to be excited by the flame’s energy.', 'इसके इलेक्ट्रॉन इतने दृढ़ता से बँधे हैं कि ज्वाला की ऊर्जा उन्हें उत्तेजित नहीं कर पाती।', 'ಅದರ ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳು ಜ್ವಾಲೆಯ ಶಕ್ತಿಯಿಂದ ಉದ್ರೇಕಗೊಳ್ಳಲಾಗದಷ್ಟು ಬಿಗಿಯಾಗಿ ಹಿಡಿಯಲ್ಪಟ್ಟಿವೆ.'))])

    lab(id='salt-analysis', bench='spot-test', setup={'kit': 'salt'}, levels=[11, 12], mode='assessment', curricula=['cbse', 'ncert', 'ka-puc'], **chem,
        keywords=['salt analysis', 'qualitative analysis', 'systematic analysis', 'cation', 'anion', 'acid radical', 'basic radical', 'group reagent'],
        title=W('Systematic salt analysis', 'क्रमबद्ध लवण विश्लेषण', 'ಕ್ರಮಬದ್ಧ ಲವಣ ವಿಶ್ಲೇಷಣೆ'),
        summary=W('Identify the cation and anion in unknown salts A–G with group reagents and confirmatory tests.', 'समूह अभिकर्मकों और पुष्टिकारी परीक्षणों से अज्ञात लवण A–G के धनायन और ऋणायन पहचानें।', 'ಗುಂಪು ಕಾರಕಗಳು ಮತ್ತು ದೃಢೀಕರಣ ಪರೀಕ್ಷೆಗಳಿಂದ ಅಜ್ಞಾತ ಲವಣ A–G ಯ ಧನಾಯನ ಮತ್ತು ಋಣಾಯನ ಗುರುತಿಸಿ.'),
        aim=W('To identify one cation and one anion in a given salt by systematic qualitative analysis.', 'क्रमबद्ध गुणात्मक विश्लेषण से दिए गए लवण में एक धनायन और एक ऋणायन पहचानना।', 'ಕ್ರಮಬದ್ಧ ಗುಣಾತ್ಮಕ ವಿಶ್ಲೇಷಣೆಯಿಂದ ಕೊಟ್ಟ ಲವಣದಲ್ಲಿ ಒಂದು ಧನಾಯನ ಮತ್ತು ಒಂದು ಋಣಾಯನ ಗುರುತಿಸುವುದು.'),
        principle=W('Anions are found with dilute and concentrated H₂SO₄ and specific reagents (BaCl₂ for sulphate, AgNO₃ for chloride). Cations are separated into groups by the solubility of their compounds: dil. HCl (group I), H₂S in acid (II), NH₄OH with NH₄Cl (III), H₂S in alkali (IV), (NH₄)₂CO₃ (V), and the rest (VI). A confirmatory test then names the ion.', 'ऋणायन तनु और सांद्र H₂SO₄ तथा विशिष्ट अभिकर्मकों (सल्फ़ेट के लिए BaCl₂, क्लोराइड के लिए AgNO₃) से पहचाने जाते हैं। धनायनों को उनके यौगिकों की विलेयता से समूहों में बाँटा जाता है: तनु HCl (समूह I), अम्ल में H₂S (II), NH₄Cl सहित NH₄OH (III), क्षार में H₂S (IV), (NH₄)₂CO₃ (V), और शेष (VI)। फिर पुष्टिकारी परीक्षण आयन का नाम बताता है।', 'ಋಣಾಯನಗಳನ್ನು ವಿರಳ ಮತ್ತು ಸಾಂದ್ರ H₂SO₄ ಹಾಗೂ ನಿರ್ದಿಷ್ಟ ಕಾರಕಗಳಿಂದ (ಸಲ್ಫೇಟ್‌ಗೆ BaCl₂, ಕ್ಲೋರೈಡ್‌ಗೆ AgNO₃) ಕಂಡುಹಿಡಿಯುತ್ತಾರೆ. ಧನಾಯನಗಳನ್ನು ಅವುಗಳ ಸಂಯುಕ್ತಗಳ ವಿಲೇಯತೆಯಿಂದ ಗುಂಪುಗಳಾಗಿ ವಿಂಗಡಿಸುತ್ತಾರೆ: ವಿರಳ HCl (ಗುಂಪು I), ಆಮ್ಲದಲ್ಲಿ H₂S (II), NH₄Cl ಸಹಿತ NH₄OH (III), ಕ್ಷಾರದಲ್ಲಿ H₂S (IV), (NH₄)₂CO₃ (V), ಮತ್ತು ಉಳಿದವು (VI). ನಂತರ ದೃಢೀಕರಣ ಪರೀಕ್ಷೆ ಅಯಾನನ್ನು ಹೆಸರಿಸುತ್ತದೆ.'),
        apparatus=[W('Test tubes, rack and holder', 'परखनलियाँ, स्टैंड और धारक', 'ಪರೀಕ್ಷಾ ನಳಿಕೆಗಳು, ಸ್ಟ್ಯಾಂಡ್ ಮತ್ತು ಹಿಡಿಕೆ'), W('Group reagents and confirmatory reagents', 'समूह अभिकर्मक और पुष्टिकारी अभिकर्मक', 'ಗುಂಪು ಕಾರಕಗಳು ಮತ್ತು ದೃಢೀಕರಣ ಕಾರಕಗಳು'), W('Bunsen burner and red litmus', 'बुन्सन बर्नर और लाल लिटमस', 'ಬನ್ಸನ್ ಬರ್ನರ್ ಮತ್ತು ಕೆಂಪು ಲಿಟ್ಮಸ್'), W('Salts A–G', 'लवण A–G', 'ಲವಣಗಳು A–G')],
        steps=[W('Note the colour of the salt and its solution.', 'लवण और उसके विलयन का रंग लिखें।', 'ಲವಣ ಮತ್ತು ಅದರ ದ್ರಾವಣದ ಬಣ್ಣ ಬರೆಯಿರಿ.'),
               W('Test for the anion: dil. H₂SO₄, conc. H₂SO₄, then BaCl₂ or AgNO₃.', 'ऋणायन के लिए परीक्षण: तनु H₂SO₄, सांद्र H₂SO₄, फिर BaCl₂ या AgNO₃.', 'ಋಣಾಯನ ಪರೀಕ್ಷೆ: ವಿರಳ H₂SO₄, ಸಾಂದ್ರ H₂SO₄, ನಂತರ BaCl₂ ಅಥವಾ AgNO₃.'),
               W('Test for NH₄⁺ by warming with NaOH.', 'NaOH के साथ गरम करके NH₄⁺ का परीक्षण करें।', 'NaOH ಜೊತೆ ಬಿಸಿಮಾಡಿ NH₄⁺ ಪರೀಕ್ಷಿಸಿ.'),
               W('Add the group reagents in order until one gives a precipitate.', 'समूह अभिकर्मक क्रम से डालें जब तक कोई अवक्षेप न दे।', 'ಒಂದು ಅವಕ್ಷೇಪ ನೀಡುವವರೆಗೆ ಗುಂಪು ಕಾರಕಗಳನ್ನು ಕ್ರಮವಾಗಿ ಸೇರಿಸಿ.'),
               W('Confirm the cation with its special test and write the formula of the salt.', 'धनायन की उसके विशेष परीक्षण से पुष्टि करें और लवण का सूत्र लिखें।', 'ಧನಾಯನವನ್ನು ಅದರ ವಿಶೇಷ ಪರೀಕ್ಷೆಯಿಂದ ದೃಢಪಡಿಸಿ ಲವಣದ ಸೂತ್ರ ಬರೆಯಿರಿ.')],
        precautions=[W('Use small quantities and add reagents drop by drop.', 'कम मात्रा लें और अभिकर्मक बूँद-बूँद डालें।', 'ಸಣ್ಣ ಪ್ರಮಾಣ ಬಳಸಿ ಕಾರಕಗಳನ್ನು ಹನಿ ಹನಿಯಾಗಿ ಸೇರಿಸಿ.'), W('Never smell gases directly: waft them towards you.', 'गैसों को कभी सीधे न सूँघें: उन्हें हाथ से अपनी ओर लाएँ।', 'ಅನಿಲಗಳನ್ನು ಎಂದೂ ನೇರವಾಗಿ ಮೂಸಬೇಡಿ: ಕೈಯಿಂದ ನಿಮ್ಮತ್ತ ಬೀಸಿ.'), W('Work with H₂S and concentrated acids in the fume cupboard.', 'H₂S और सांद्र अम्लों के साथ धूम्र कक्ष में काम करें।', 'H₂S ಮತ್ತು ಸಾಂದ್ರ ಆಮ್ಲಗಳೊಂದಿಗೆ ಧೂಮ ಕಪಾಟಿನಲ್ಲಿ ಕೆಲಸ ಮಾಡಿ.'), GOGGLES],
        conclusion=W('By testing systematically, each unknown salt’s anion and cation are identified and confirmed (for example salt A is copper(II) sulphate).', 'क्रमबद्ध परीक्षण से हर अज्ञात लवण के ऋणायन और धनायन पहचाने और पुष्ट किए जाते हैं (उदाहरण के लिए लवण A कॉपर(II) सल्फ़ेट है)।', 'ಕ್ರಮಬದ್ಧ ಪರೀಕ್ಷೆಯಿಂದ ಪ್ರತಿ ಅಜ್ಞಾತ ಲವಣದ ಋಣಾಯನ ಮತ್ತು ಧನಾಯನ ಗುರುತಿಸಿ ದೃಢಪಡಿಸಲಾಗುತ್ತದೆ (ಉದಾಹರಣೆಗೆ ಲವಣ A ತಾಮ್ರ(II) ಸಲ್ಫೇಟ್).'),
        viva=[Q(W('Why is NH₄Cl added before NH₄OH in group III?', 'समूह III में NH₄OH से पहले NH₄Cl क्यों डालते हैं?', 'ಗುಂಪು III ರಲ್ಲಿ NH₄OH ಮೊದಲು NH₄Cl ಏಕೆ ಸೇರಿಸುತ್ತಾರೆ?'), W('Common-ion effect: it lowers [OH⁻] so only group III hydroxides precipitate, not Mg(OH)₂.', 'समान आयन प्रभाव: यह [OH⁻] घटाता है ताकि केवल समूह III के हाइड्रॉक्साइड अवक्षेपित हों, Mg(OH)₂ नहीं।', 'ಸಮಾನ ಅಯಾನು ಪರಿಣಾಮ: ಅದು [OH⁻] ಕಡಿಮೆ ಮಾಡುತ್ತದೆ; ಗುಂಪು III ಹೈಡ್ರಾಕ್ಸೈಡ್‌ಗಳು ಮಾತ್ರ ಅವಕ್ಷೇಪಗೊಳ್ಳುತ್ತವೆ, Mg(OH)₂ ಅಲ್ಲ.')),
              Q(W('What is the group reagent for group I?', 'समूह I का समूह अभिकर्मक क्या है?', 'ಗುಂಪು I ರ ಗುಂಪು ಕಾರಕ ಯಾವುದು?'), W('Dilute HCl (it precipitates Pb²⁺ as PbCl₂).', 'तनु HCl (यह Pb²⁺ को PbCl₂ के रूप में अवक्षेपित करता है)।', 'ವಿರಳ HCl (ಅದು Pb²⁺ ಅನ್ನು PbCl₂ ಆಗಿ ಅವಕ್ಷೇಪಿಸುತ್ತದೆ).')),
              Q(W('Which test confirms Fe³⁺?', 'Fe³⁺ की पुष्टि कौन-सा परीक्षण करता है?', 'Fe³⁺ ಅನ್ನು ಯಾವ ಪರೀಕ್ಷೆ ದೃಢಪಡಿಸುತ್ತದೆ?'), W('Potassium ferrocyanide gives Prussian blue.', 'पोटैशियम फ़ेरोसायनाइड प्रशियन नीला देता है।', 'ಪೊಟ್ಯಾಸಿಯಂ ಫೆರೋಸಯನೈಡ್ ಪ್ರಷ್ಯನ್ ನೀಲಿ ನೀಡುತ್ತದೆ.'))])

    lab(id='food-tests', bench='spot-test', setup={'kit': 'food'}, subject='Biology', domain='biology', levels=[9, 12], mode='guided', curricula=['cbse', 'ncert'],
        keywords=['food tests', 'carbohydrates', 'proteins', 'fats', 'starch', 'reducing sugar', 'biuret', "benedict's test", 'biomolecules', 'nutrition'],
        title=W('Tests for starch, sugar, protein and fat', 'स्टार्च, शर्करा, प्रोटीन और वसा के परीक्षण', 'ಪಿಷ್ಟ, ಸಕ್ಕರೆ, ಪ್ರೋಟೀನ್ ಮತ್ತು ಕೊಬ್ಬಿನ ಪರೀಕ್ಷೆಗಳು'),
        summary=W('Use iodine, Benedict’s, biuret and Sudan III to find what each food contains.', 'आयोडीन, बेनेडिक्ट, बाइयूरेट और सूडान III से पता करें कि हर खाद्य में क्या है।', 'ಅಯೋಡಿನ್, ಬೆನೆಡಿಕ್ಟ್, ಬೈಯುರೆಟ್ ಮತ್ತು ಸೂಡಾನ್ III ಬಳಸಿ ಪ್ರತಿ ಆಹಾರದಲ್ಲಿ ಏನಿದೆ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To test for the presence of starch, reducing sugar, protein and fat in given foods.', 'दिए गए खाद्यों में स्टार्च, अपचायी शर्करा, प्रोटीन और वसा की उपस्थिति का परीक्षण करना।', 'ಕೊಟ್ಟ ಆಹಾರಗಳಲ್ಲಿ ಪಿಷ್ಟ, ಅಪಕರ್ಷಕ ಸಕ್ಕರೆ, ಪ್ರೋಟೀನ್ ಮತ್ತು ಕೊಬ್ಬಿನ ಇರುವಿಕೆ ಪರೀಕ್ಷಿಸುವುದು.'),
        principle=W('Iodine forms a blue-black complex with starch. Reducing sugars reduce blue Cu²⁺ in Benedict’s solution to brick-red Cu₂O on boiling. Peptide bonds give a violet colour with Cu²⁺ in alkali (biuret). Fats dissolve the red dye Sudan III and leave translucent spots on paper.', 'आयोडीन स्टार्च के साथ नीला-काला संकुल बनाता है। अपचायी शर्करा उबालने पर बेनेडिक्ट विलयन के नीले Cu²⁺ को ईंट-लाल Cu₂O में अपचयित करती है। पेप्टाइड बंध क्षार में Cu²⁺ के साथ बैंगनी रंग देते हैं (बाइयूरेट)। वसा लाल रंजक सूडान III को घोल लेती है और कागज़ पर पारभासी धब्बे छोड़ती है।', 'ಅಯೋಡಿನ್ ಪಿಷ್ಟದೊಂದಿಗೆ ನೀಲಿ-ಕಪ್ಪು ಸಂಕೀರ್ಣ ರೂಪಿಸುತ್ತದೆ. ಅಪಕರ್ಷಕ ಸಕ್ಕರೆಗಳು ಕುದಿಸಿದಾಗ ಬೆನೆಡಿಕ್ಟ್ ದ್ರಾವಣದ ನೀಲಿ Cu²⁺ ಅನ್ನು ಇಟ್ಟಿಗೆ-ಕೆಂಪು Cu₂O ಆಗಿ ಅಪಕರ್ಷಿಸುತ್ತವೆ. ಪೆಪ್ಟೈಡ್ ಬಂಧಗಳು ಕ್ಷಾರದಲ್ಲಿ Cu²⁺ ಜೊತೆ ನೇರಳೆ ಬಣ್ಣ ನೀಡುತ್ತವೆ (ಬೈಯುರೆಟ್). ಕೊಬ್ಬುಗಳು ಕೆಂಪು ಬಣ್ಣ ಸೂಡಾನ್ III ಅನ್ನು ಕರಗಿಸುತ್ತವೆ, ಕಾಗದದ ಮೇಲೆ ಅರೆಪಾರದರ್ಶಕ ಕಲೆ ಬಿಡುತ್ತವೆ.'),
        apparatus=[W('Test tubes and a water bath', 'परखनलियाँ और जल ऊष्मक', 'ಪರೀಕ್ಷಾ ನಳಿಕೆಗಳು ಮತ್ತು ನೀರಿನ ತೊಟ್ಟಿ'), W("Iodine, Benedict's solution, NaOH and CuSO₄, Sudan III", "आयोडीन, बेनेडिक्ट विलयन, NaOH और CuSO₄, सूडान III", "ಅಯೋಡಿನ್, ಬೆನೆಡಿಕ್ಟ್ ದ್ರಾವಣ, NaOH ಮತ್ತು CuSO₄, ಸೂಡಾನ್ III"), W('Food samples: glucose, starch, egg albumin, oil, milk', 'खाद्य नमूने: ग्लूकोज़, स्टार्च, अंडे का एल्ब्यूमिन, तेल, दूध', 'ಆಹಾರ ಮಾದರಿಗಳು: ಗ್ಲೂಕೋಸ್, ಪಿಷ್ಟ, ಮೊಟ್ಟೆಯ ಆಲ್ಬುಮಿನ್, ಎಣ್ಣೆ, ಹಾಲು'), W('Brown paper', 'भूरा कागज़', 'ಕಂದು ಕಾಗದ')],
        steps=[W('Put a little of a food in a tube and add a few drops of iodine; note the colour.', 'परखनली में थोड़ा खाद्य लेकर आयोडीन की कुछ बूँदें डालें; रंग लिखें।', 'ನಳಿಕೆಯಲ್ಲಿ ಸ್ವಲ್ಪ ಆಹಾರ ಹಾಕಿ ಕೆಲವು ಹನಿ ಅಯೋಡಿನ್ ಸೇರಿಸಿ; ಬಣ್ಣ ಬರೆಯಿರಿ.'),
               W("Boil a fresh sample with Benedict's solution for 2 minutes.", 'नए नमूने को बेनेडिक्ट विलयन के साथ 2 मिनट उबालें।', 'ಹೊಸ ಮಾದರಿಯನ್ನು ಬೆನೆಡಿಕ್ಟ್ ದ್ರಾವಣದೊಂದಿಗೆ 2 ನಿಮಿಷ ಕುದಿಸಿ.'),
               W('Add NaOH and then a drop of CuSO₄ to a third sample (biuret test).', 'तीसरे नमूने में NaOH और फिर CuSO₄ की एक बूँद डालें (बाइयूरेट परीक्षण)।', 'ಮೂರನೇ ಮಾದರಿಗೆ NaOH ಮತ್ತು ನಂತರ ಒಂದು ಹನಿ CuSO₄ ಸೇರಿಸಿ (ಬೈಯುರೆಟ್ ಪರೀಕ್ಷೆ).'),
               W('Shake a fourth sample with Sudan III, and rub some on paper.', 'चौथे नमूने को सूडान III के साथ हिलाएँ, और थोड़ा कागज़ पर रगड़ें।', 'ನಾಲ್ಕನೇ ಮಾದರಿಯನ್ನು ಸೂಡಾನ್ III ಜೊತೆ ಅಲುಗಾಡಿಸಿ, ಸ್ವಲ್ಪ ಕಾಗದದ ಮೇಲೆ ಉಜ್ಜಿ.'),
               W('Record what each food contains.', 'लिखें कि हर खाद्य में क्या है।', 'ಪ್ರತಿ ಆಹಾರದಲ್ಲಿ ಏನಿದೆ ದಾಖಲಿಸಿ.')],
        precautions=[W('Use clean tubes for every test.', 'हर परीक्षण के लिए साफ़ परखनलियाँ लें।', 'ಪ್ರತಿ ಪರೀಕ್ಷೆಗೆ ಸ್ವಚ್ಛ ನಳಿಕೆಗಳನ್ನು ಬಳಸಿ.'), W('Point the tube away from people when heating.', 'गरम करते समय परखनली का मुँह लोगों से दूर रखें।', 'ಬಿಸಿಮಾಡುವಾಗ ನಳಿಕೆಯ ಬಾಯಿ ಜನರಿಂದ ದೂರವಿರಲಿ.'), W('Add only a drop of CuSO₄ in the biuret test.', 'बाइयूरेट परीक्षण में CuSO₄ की केवल एक बूँद डालें।', 'ಬೈಯುರೆಟ್ ಪರೀಕ್ಷೆಯಲ್ಲಿ CuSO₄ ಒಂದೇ ಹನಿ ಸೇರಿಸಿ.')],
        conclusion=W('Starch gives blue-black with iodine, glucose brick-red with Benedict’s, albumin violet with biuret and oil a red layer with Sudan III; milk contains sugar, protein and fat.', 'स्टार्च आयोडीन से नीला-काला, ग्लूकोज़ बेनेडिक्ट से ईंट-लाल, एल्ब्यूमिन बाइयूरेट से बैंगनी और तेल सूडान III से लाल परत देता है; दूध में शर्करा, प्रोटीन और वसा हैं।', 'ಪಿಷ್ಟ ಅಯೋಡಿನ್‌ನಿಂದ ನೀಲಿ-ಕಪ್ಪು, ಗ್ಲೂಕೋಸ್ ಬೆನೆಡಿಕ್ಟ್‌ನಿಂದ ಇಟ್ಟಿಗೆ-ಕೆಂಪು, ಆಲ್ಬುಮಿನ್ ಬೈಯುರೆಟ್‌ನಿಂದ ನೇರಳೆ, ಎಣ್ಣೆ ಸೂಡಾನ್ III ನಿಂದ ಕೆಂಪು ಪದರ ನೀಡುತ್ತವೆ; ಹಾಲಿನಲ್ಲಿ ಸಕ್ಕರೆ, ಪ್ರೋಟೀನ್ ಮತ್ತು ಕೊಬ್ಬು ಇವೆ.'),
        viva=[Q(W('Is sucrose a reducing sugar?', 'क्या सुक्रोज़ अपचायी शर्करा है?', 'ಸುಕ್ರೋಸ್ ಅಪಕರ್ಷಕ ಸಕ್ಕರೆಯೇ?'), W('No: it gives a negative Benedict’s test unless first hydrolysed.', 'नहीं: पहले जल-अपघटन के बिना यह बेनेडिक्ट परीक्षण में ऋणात्मक है।', 'ಇಲ್ಲ: ಮೊದಲು ಜಲವಿಭಜನೆ ಮಾಡದಿದ್ದರೆ ಬೆನೆಡಿಕ್ಟ್ ಪರೀಕ್ಷೆ ಋಣಾತ್ಮಕ.')),
              Q(W('Which nutrient gives energy fastest?', 'कौन-सा पोषक सबसे जल्दी ऊर्जा देता है?', 'ಯಾವ ಪೋಷಕಾಂಶ ಅತಿ ಬೇಗ ಶಕ್ತಿ ನೀಡುತ್ತದೆ?'), W('Carbohydrates such as glucose.', 'ग्लूकोज़ जैसे कार्बोहाइड्रेट।', 'ಗ್ಲೂಕೋಸ್‌ನಂತಹ ಕಾರ್ಬೋಹೈಡ್ರೇಟ್‌ಗಳು.')),
              Q(W('What does the biuret test detect?', 'बाइयूरेट परीक्षण क्या पहचानता है?', 'ಬೈಯುರೆಟ್ ಪರೀಕ್ಷೆ ಏನನ್ನು ಪತ್ತೆಹಚ್ಚುತ್ತದೆ?'), W('Peptide bonds, so proteins.', 'पेप्टाइड बंध, अर्थात प्रोटीन।', 'ಪೆಪ್ಟೈಡ್ ಬಂಧಗಳು, ಅಂದರೆ ಪ್ರೋಟೀನ್‌ಗಳು.'))])

    lab(id='toxicology-spot-tests', bench='spot-test', setup={'kit': 'toxicology'}, subject='Forensics', domain='forensics', levels=[11, 12, 'ug'], mode='assessment', curricula=['forensics'],
        keywords=['forensic toxicology', 'toxicology', 'presumptive test', 'spot test', 'colour test', 'poison', 'drugs'],
        title=W('Forensic toxicology: presumptive colour tests', 'न्यायालयिक विषविज्ञान: प्रारंभिक रंग परीक्षण', 'ವಿಧಿವಿಜ್ಞಾನ ವಿಷಶಾಸ್ತ್ರ: ಪ್ರಾಥಮಿಕ ಬಣ್ಣ ಪರೀಕ್ಷೆಗಳು'),
        summary=W('Screen seized exhibits with Marquis, ferric chloride, Scott and Reinsch tests and decide which need laboratory confirmation.', 'जब्त प्रदर्शों की मार्क्विस, फ़ेरिक क्लोराइड, स्कॉट और राइन्श परीक्षणों से जाँच करें और तय करें कि किनकी प्रयोगशाला पुष्टि चाहिए।', 'ವಶಪಡಿಸಿದ ವಸ್ತುಗಳನ್ನು ಮಾರ್ಕ್ವಿಸ್, ಫೆರಿಕ್ ಕ್ಲೋರೈಡ್, ಸ್ಕಾಟ್ ಮತ್ತು ರೈನ್ಶ್ ಪರೀಕ್ಷೆಗಳಿಂದ ಪರೀಕ್ಷಿಸಿ ಯಾವುದಕ್ಕೆ ಪ್ರಯೋಗಾಲಯ ದೃಢೀಕರಣ ಬೇಕು ನಿರ್ಧರಿಸಿ.'),
        aim=W('To screen unknown exhibits for drugs and poisons with presumptive colour tests.', 'प्रारंभिक रंग परीक्षणों से अज्ञात प्रदर्शों में औषधियों और विषों की जाँच करना।', 'ಪ್ರಾಥಮಿಕ ಬಣ್ಣ ಪರೀಕ್ಷೆಗಳಿಂದ ಅಜ್ಞಾತ ವಸ್ತುಗಳಲ್ಲಿ ಔಷಧ ಮತ್ತು ವಿಷಗಳನ್ನು ಪರೀಕ್ಷಿಸುವುದು.'),
        principle=W('A presumptive test gives a colour with a class of compounds: Marquis (formaldehyde in sulphuric acid) turns purple with opiates and orange-brown with amphetamines; ferric chloride turns violet with salicylates; cobalt thiocyanate (Scott) turns blue with cocaine; in the Reinsch test arsenic or mercury deposits on copper. A positive result only narrows the possibilities; confirmation needs chromatography or spectroscopy.', 'प्रारंभिक परीक्षण यौगिकों के एक वर्ग के साथ रंग देता है: मार्क्विस (सल्फ़्यूरिक अम्ल में फ़ॉर्मैल्डिहाइड) ओपिएट के साथ बैंगनी और ऐम्फ़ेटामीन के साथ नारंगी-भूरा; फ़ेरिक क्लोराइड सैलिसिलेट के साथ बैंगनी; कोबाल्ट थायोसायनेट (स्कॉट) कोकेन के साथ नीला; राइन्श परीक्षण में आर्सेनिक या पारा ताँबे पर जमता है। धनात्मक परिणाम केवल संभावनाएँ घटाता है; पुष्टि के लिए वर्णलेखन या स्पेक्ट्रमिकी चाहिए।', 'ಪ್ರಾಥಮಿಕ ಪರೀಕ್ಷೆ ಒಂದು ವರ್ಗದ ಸಂಯುಕ್ತಗಳೊಂದಿಗೆ ಬಣ್ಣ ನೀಡುತ್ತದೆ: ಮಾರ್ಕ್ವಿಸ್ (ಸಲ್ಫ್ಯೂರಿಕ್ ಆಮ್ಲದಲ್ಲಿ ಫಾರ್ಮಾಲ್ಡಿಹೈಡ್) ಓಪಿಯೇಟ್‌ಗಳೊಂದಿಗೆ ನೇರಳೆ, ಆಂಫೆಟಮೀನ್‌ಗಳೊಂದಿಗೆ ಕಿತ್ತಳೆ-ಕಂದು; ಫೆರಿಕ್ ಕ್ಲೋರೈಡ್ ಸ್ಯಾಲಿಸಿಲೇಟ್‌ಗಳೊಂದಿಗೆ ನೇರಳೆ; ಕೋಬಾಲ್ಟ್ ಥಯೋಸಯನೇಟ್ (ಸ್ಕಾಟ್) ಕೊಕೇನ್‌ನೊಂದಿಗೆ ನೀಲಿ; ರೈನ್ಶ್ ಪರೀಕ್ಷೆಯಲ್ಲಿ ಆರ್ಸೆನಿಕ್ ಅಥವಾ ಪಾದರಸ ತಾಮ್ರದ ಮೇಲೆ ಶೇಖರಣೆಯಾಗುತ್ತದೆ. ಧನಾತ್ಮಕ ಫಲಿತಾಂಶ ಸಾಧ್ಯತೆಗಳನ್ನು ಕಿರಿದಾಗಿಸುತ್ತದೆ ಅಷ್ಟೇ; ದೃಢೀಕರಣಕ್ಕೆ ವರ್ಣರೇಖನ ಅಥವಾ ರೋಹಿತಮಾಪನ ಬೇಕು.'),
        apparatus=[W('Spot plate and droppers', 'स्पॉट प्लेट और ड्रॉपर', 'ಸ್ಪಾಟ್ ಪ್ಲೇಟ್ ಮತ್ತು ಡ್ರಾಪರ್‌ಗಳು'), W('Marquis, ferric chloride and Scott reagents', 'मार्क्विस, फ़ेरिक क्लोराइड और स्कॉट अभिकर्मक', 'ಮಾರ್ಕ್ವಿಸ್, ಫೆರಿಕ್ ಕ್ಲೋರೈಡ್ ಮತ್ತು ಸ್ಕಾಟ್ ಕಾರಕಗಳು'), W('Copper strips and dilute HCl (Reinsch)', 'ताँबे की पट्टियाँ और तनु HCl (राइन्श)', 'ತಾಮ್ರದ ಪಟ್ಟಿಗಳು ಮತ್ತು ವಿರಳ HCl (ರೈನ್ಶ್)'), W('Exhibits 1–6, gloves, goggles and evidence labels', 'प्रदर्श 1–6, दस्ताने, चश्मा और साक्ष्य लेबल', 'ವಸ್ತುಗಳು 1–6, ಕೈಗವಸು, ಕನ್ನಡಕ ಮತ್ತು ಸಾಕ್ಷ್ಯ ಹಣೆಪಟ್ಟಿಗಳು')],
        steps=[W('Put a few milligrams of each exhibit in separate wells of the spot plate.', 'हर प्रदर्श के कुछ मिलीग्राम स्पॉट प्लेट के अलग गड्ढों में रखें।', 'ಪ್ರತಿ ವಸ್ತುವಿನ ಕೆಲವು ಮಿಲಿಗ್ರಾಂ ಅನ್ನು ಸ್ಪಾಟ್ ಪ್ಲೇಟ್‌ನ ಬೇರೆ ಬೇರೆ ಗುಂಡಿಗಳಲ್ಲಿಡಿ.'),
               W('Add one drop of reagent and note any colour within a minute.', 'अभिकर्मक की एक बूँद डालें और एक मिनट के भीतर कोई रंग देखें।', 'ಕಾರಕದ ಒಂದು ಹನಿ ಸೇರಿಸಿ ಒಂದು ನಿಮಿಷದೊಳಗಿನ ಯಾವುದೇ ಬಣ್ಣ ಗಮನಿಸಿ.'),
               W('Run a blank (reagent alone) and a known control alongside.', 'साथ में एक रिक्त (केवल अभिकर्मक) और एक ज्ञात नियंत्रण चलाएँ।', 'ಜೊತೆಗೆ ಒಂದು ಖಾಲಿ (ಕಾರಕ ಮಾತ್ರ) ಮತ್ತು ತಿಳಿದ ನಿಯಂತ್ರಣ ನಡೆಸಿ.'),
               W('Repeat with each reagent and record every result.', 'हर अभिकर्मक के साथ दोहराएँ और हर परिणाम लिखें।', 'ಪ್ರತಿ ಕಾರಕದೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ ಪ್ರತಿ ಫಲಿತಾಂಶ ದಾಖಲಿಸಿ.'),
               W('List which exhibits must go for confirmatory analysis.', 'सूची बनाएँ कि किन प्रदर्शों को पुष्टिकारी विश्लेषण के लिए भेजना है।', 'ಯಾವ ವಸ್ತುಗಳು ದೃಢೀಕರಣ ವಿಶ್ಲೇಷಣೆಗೆ ಹೋಗಬೇಕು ಪಟ್ಟಿ ಮಾಡಿ.')],
        precautions=[W('Marquis reagent contains concentrated sulphuric acid: wear gloves and goggles.', 'मार्क्विस अभिकर्मक में सांद्र सल्फ़्यूरिक अम्ल है: दस्ताने और चश्मा पहनें।', 'ಮಾರ್ಕ್ವಿಸ್ ಕಾರಕದಲ್ಲಿ ಸಾಂದ್ರ ಸಲ್ಫ್ಯೂರಿಕ್ ಆಮ್ಲ ಇದೆ: ಕೈಗವಸು ಮತ್ತು ಕನ್ನಡಕ ಧರಿಸಿ.'), W('Never taste or smell exhibits; keep the chain of custody.', 'प्रदर्शों को कभी न चखें या सूँघें; अभिरक्षा की शृंखला बनाए रखें।', 'ವಸ್ತುಗಳನ್ನು ಎಂದೂ ರುಚಿ ನೋಡಬೇಡಿ ಅಥವಾ ಮೂಸಬೇಡಿ; ಕಸ್ಟಡಿ ಸರಪಳಿ ಕಾಪಾಡಿ.'), W('Use the smallest amount so the rest is kept for the laboratory.', 'सबसे कम मात्रा लें ताकि शेष प्रयोगशाला के लिए बचे।', 'ಉಳಿದುದು ಪ್ರಯೋಗಾಲಯಕ್ಕೆ ಉಳಿಯುವಂತೆ ಅತಿ ಕಡಿಮೆ ಪ್ರಮಾಣ ಬಳಸಿ.')],
        conclusion=W('The colour tests sort the exhibits into presumptive classes (opiate, amphetamine, salicylate, cocaine, arsenic) and show which are negative; every positive must be confirmed by laboratory analysis before it is reported.', 'रंग परीक्षण प्रदर्शों को प्रारंभिक वर्गों (ओपिएट, ऐम्फ़ेटामीन, सैलिसिलेट, कोकेन, आर्सेनिक) में बाँटते हैं और दिखाते हैं कि कौन ऋणात्मक हैं; हर धनात्मक की रिपोर्ट से पहले प्रयोगशाला विश्लेषण से पुष्टि आवश्यक है।', 'ಬಣ್ಣ ಪರೀಕ್ಷೆಗಳು ವಸ್ತುಗಳನ್ನು ಪ್ರಾಥಮಿಕ ವರ್ಗಗಳಾಗಿ (ಓಪಿಯೇಟ್, ಆಂಫೆಟಮೀನ್, ಸ್ಯಾಲಿಸಿಲೇಟ್, ಕೊಕೇನ್, ಆರ್ಸೆನಿಕ್) ವಿಂಗಡಿಸಿ ಯಾವುವು ಋಣಾತ್ಮಕ ಎಂದು ತೋರಿಸುತ್ತವೆ; ಪ್ರತಿ ಧನಾತ್ಮಕವನ್ನು ವರದಿ ಮಾಡುವ ಮೊದಲು ಪ್ರಯೋಗಾಲಯ ವಿಶ್ಲೇಷಣೆಯಿಂದ ದೃಢಪಡಿಸಬೇಕು.'),
        viva=[Q(W('Why is a presumptive test not enough in court?', 'न्यायालय में प्रारंभिक परीक्षण पर्याप्त क्यों नहीं?', 'ನ್ಯಾಯಾಲಯದಲ್ಲಿ ಪ್ರಾಥಮಿಕ ಪರೀಕ್ಷೆ ಏಕೆ ಸಾಕಾಗುವುದಿಲ್ಲ?'), W('Many harmless substances give similar colours (false positives); only a confirmatory test identifies the compound.', 'कई हानिरहित पदार्थ समान रंग देते हैं (मिथ्या धनात्मक); केवल पुष्टिकारी परीक्षण यौगिक पहचानता है।', 'ಹಲವು ನಿರುಪದ್ರವ ವಸ್ತುಗಳು ಇದೇ ಬಣ್ಣ ನೀಡುತ್ತವೆ (ತಪ್ಪು ಧನಾತ್ಮಕ); ದೃಢೀಕರಣ ಪರೀಕ್ಷೆ ಮಾತ್ರ ಸಂಯುಕ್ತವನ್ನು ಗುರುತಿಸುತ್ತದೆ.')),
              Q(W('Why run a blank?', 'रिक्त क्यों चलाते हैं?', 'ಖಾಲಿಯನ್ನು ಏಕೆ ನಡೆಸುತ್ತಾರೆ?'), W('To show the reagent itself gives no colour.', 'यह दिखाने के लिए कि अभिकर्मक स्वयं कोई रंग नहीं देता।', 'ಕಾರಕ ತಾನೇ ಯಾವ ಬಣ್ಣವೂ ನೀಡುವುದಿಲ್ಲ ಎಂದು ತೋರಿಸಲು.')),
              Q(W('Name a confirmatory technique.', 'एक पुष्टिकारी तकनीक बताइए।', 'ಒಂದು ದೃಢೀಕರಣ ತಂತ್ರ ಹೆಸರಿಸಿ.'), W('Gas chromatography–mass spectrometry (GC–MS).', 'गैस वर्णलेखन–द्रव्यमान स्पेक्ट्रममिति (GC–MS)।', 'ಅನಿಲ ವರ್ಣರೇಖನ–ದ್ರವ್ಯರಾಶಿ ರೋಹಿತಮಾಪನ (GC–MS).'))])
